insert into modules (id, track_id, title, description, slug, sort_order, unlock_rule, is_active)
values
  ('00000000-0000-0000-0000-000000000201', '00000000-0000-0000-0000-000000000101', 'Primeiros SELECTs', 'Escolha colunas, aliases, LIMIT e expressoes simples.', 'primeiros-selects', 1, null, true),
  ('00000000-0000-0000-0000-000000000202', '00000000-0000-0000-0000-000000000101', 'Filtros com WHERE', 'Use comparacoes simples para separar as linhas certas.', 'filtros-where', 2, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000203', '00000000-0000-0000-0000-000000000101', 'Operadores do WHERE', 'Combine AND, OR, IN, BETWEEN, LIKE, NULL e NOT.', 'operadores-where', 3, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000204', '00000000-0000-0000-0000-000000000101', 'Ordenacao e LIMIT', 'Controle a ordem, o topo e recortes de resultados.', 'ordenacao-e-limit', 4, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000205', '00000000-0000-0000-0000-000000000101', 'Agregacoes com SELECT', 'Resuma dados com COUNT, SUM, AVG, MIN, MAX e HAVING.', 'agregacoes-select', 5, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000206', '00000000-0000-0000-0000-000000000101', 'JOINs basicos', 'Cruze tabelas relacionadas por chaves estrangeiras.', 'joins-basicos', 6, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000207', '00000000-0000-0000-0000-000000000101', 'JOINs intermediarios', 'Use LEFT JOIN, multiplos JOINs e agregacoes relacionadas.', 'joins-intermediarios', 7, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000208', '00000000-0000-0000-0000-000000000101', 'CTEs', 'Organize consultas em etapas com WITH.', 'ctes', 8, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000209', '00000000-0000-0000-0000-000000000101', 'UNION e combinacoes', 'Una consultas compativeis com UNION e UNION ALL.', 'union-combinacoes', 9, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000210', '00000000-0000-0000-0000-000000000101', 'Revisao guiada SELECT', 'Resolva desafios integrando filtros, joins, CTEs e union.', 'revisao-select', 10, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000211', '00000000-0000-0000-0000-000000000101', 'Escrita e DDL no sandbox', 'Pratique CREATE, INSERT, DELETE e DROP com validacao isolada.', 'escrita-ddl-sandbox', 11, '{"type":"previous_module_completion","percentage":70}', true),
  ('00000000-0000-0000-0000-000000000212', '00000000-0000-0000-0000-000000000101', 'Perguntas de negocio', 'Responda perguntas de negocio com consultas analiticas.', 'perguntas-de-negocio', 12, '{"type":"previous_module_completion","percentage":70}', false)
