insert into challenges (id, module_id, title, slug, type, difficulty, prompt, starter_sql, expected_sql, expected_columns, allowed_tables, setup_sql, validation_sql, base_points, explanation, tags, sort_order, is_active)
values
  ('00000000-0000-0000-0000-000000000301', '00000000-0000-0000-0000-000000000201', 'Nomes e emails dos clientes', 'nomes-emails-clientes', 'free_select', 'easy', 'Liste nome completo e email dos clientes. Ordene pelo nome e limite em 5 linhas.', null, 'SELECT full_name, email FROM challenge_data.customers ORDER BY full_name LIMIT 5', array['full_name', 'email'], array['customers'], null, null, 10, 'SELECT define as colunas, ORDER BY estabiliza a ordem e LIMIT reduz o retorno.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000302', '00000000-0000-0000-0000-000000000201', 'Catalogo resumido de produtos', 'catalogo-resumido-produtos', 'free_select', 'easy', 'Liste nome, SKU e preco dos produtos. Ordene pelo nome e limite em 8 linhas.', null, 'SELECT name, sku, price FROM challenge_data.products ORDER BY name LIMIT 8', array['name', 'sku', 'price'], array['products'], null, null, 10, 'Selecionar apenas colunas uteis deixa a consulta mais legivel.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000303', '00000000-0000-0000-0000-000000000201', 'Apelidos para colunas', 'apelidos-para-colunas', 'free_select', 'easy', 'Liste produtos com as colunas product_name e sale_price. Ordene pelo maior preco e limite em 5.', null, 'SELECT name AS product_name, price AS sale_price FROM challenge_data.products ORDER BY sale_price DESC LIMIT 5', array['product_name', 'sale_price'], array['products'], null, null, 10, 'AS cria nomes de saida mais claros para quem le o resultado.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000304', '00000000-0000-0000-0000-000000000201', 'Margem simples por produto', 'margem-simples-produto', 'free_select', 'easy', 'Liste nome e margem bruta dos produtos usando price - cost como gross_margin. Ordene pela maior margem e limite em 5.', null, 'SELECT name, price - cost AS gross_margin FROM challenge_data.products ORDER BY gross_margin DESC LIMIT 5', array['name', 'gross_margin'], array['products'], null, null, 10, 'Expressoes calculadas podem aparecer diretamente no SELECT.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000305', '00000000-0000-0000-0000-000000000201', 'Resumo dos primeiros pedidos', 'resumo-primeiros-pedidos', 'free_select', 'easy', 'Liste numero, status e total dos pedidos. Ordene pela data do pedido e limite em 6 linhas.', null, 'SELECT order_number, status, total_amount FROM challenge_data.orders ORDER BY order_date LIMIT 6', array['order_number', 'status', 'total_amount'], array['orders'], null, null, 10, 'Um SELECT pode montar uma visao curta de acompanhamento operacional.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000306', '00000000-0000-0000-0000-000000000201', 'Estados sem repeticao', 'estados-sem-repeticao', 'free_select', 'easy', 'Liste os estados dos clientes sem repeticao, em ordem alfabetica.', null, 'SELECT DISTINCT state FROM challenge_data.customers ORDER BY state', array['state'], array['customers'], null, null, 10, 'DISTINCT remove valores duplicados da projecao escolhida.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000307', '00000000-0000-0000-0000-000000000201', 'Tres pedidos mais recentes', 'tres-pedidos-mais-recentes', 'free_select', 'easy', 'Liste numero e data dos 3 pedidos mais recentes.', null, 'SELECT order_number, order_date FROM challenge_data.orders ORDER BY order_date DESC LIMIT 3', array['order_number', 'order_date'], array['orders'], null, null, 10, 'ORDER BY DESC junto com LIMIT retorna o topo cronologico.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000308', '00000000-0000-0000-0000-000000000201', 'Metodos de pagamento disponiveis', 'metodos-pagamento-disponiveis', 'free_select', 'easy', 'Liste os metodos de pagamento sem repeticao em ordem alfabetica.', null, 'SELECT DISTINCT payment_method FROM challenge_data.payments ORDER BY payment_method', array['payment_method'], array['payments'], null, null, 10, 'DISTINCT tambem e util para descobrir valores de dominio.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000309', '00000000-0000-0000-0000-000000000201', 'Rotulo do pedido', 'rotulo-do-pedido', 'free_select', 'medium', 'Crie a coluna order_label juntando order_number, espaco, hifen, espaco e status. Ordene pelo numero do pedido e limite em 5.', null, 'SELECT order_number || '' - '' || status AS order_label FROM challenge_data.orders ORDER BY order_number LIMIT 5', array['order_label'], array['orders'], null, null, 20, 'O operador || concatena textos no PostgreSQL.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000310', '00000000-0000-0000-0000-000000000201', 'Estoque em ordem de urgencia', 'estoque-ordem-urgencia', 'free_select', 'medium', 'Liste nome, ativo e quantidade em estoque dos produtos. Ordene pelo menor estoque e depois pelo nome. Limite em 10.', null, 'SELECT name, active, stock_quantity FROM challenge_data.products ORDER BY stock_quantity ASC, name ASC LIMIT 10', array['name', 'active', 'stock_quantity'], array['products'], null, null, 20, 'Mais de uma coluna no ORDER BY resolve empates de forma previsivel.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000311', '00000000-0000-0000-0000-000000000202', 'Clientes de Rondonia', 'clientes-de-rondonia-select', 'free_select', 'easy', 'Liste nome, email e cidade dos clientes que moram em Rondonia. Ordene pelo nome.', null, 'SELECT full_name, email, city FROM challenge_data.customers WHERE state = ''Rondonia'' ORDER BY full_name', array['full_name', 'email', 'city'], array['customers'], null, null, 10, 'WHERE com igualdade encontra linhas com um valor especifico.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000312', '00000000-0000-0000-0000-000000000202', 'Produtos ativos', 'produtos-ativos', 'free_select', 'easy', 'Liste nome, SKU e estoque dos produtos ativos. Ordene pelo nome.', null, 'SELECT name, sku, stock_quantity FROM challenge_data.products WHERE active = true ORDER BY name', array['name', 'sku', 'stock_quantity'], array['products'], null, null, 10, 'Colunas booleanas podem ser filtradas com true ou false.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000313', '00000000-0000-0000-0000-000000000202', 'Produtos acima de 500', 'produtos-acima-500', 'free_select', 'easy', 'Liste nome e preco dos produtos com preco maior que 500. Ordene do maior para o menor.', null, 'SELECT name, price FROM challenge_data.products WHERE price > 500 ORDER BY price DESC, name', array['name', 'price'], array['products'], null, null, 10, 'Operadores de comparacao permitem filtrar faixas abertas.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000314', '00000000-0000-0000-0000-000000000202', 'Pedidos pagos', 'pedidos-pagos', 'free_select', 'easy', 'Liste numero, status e total dos pedidos com status paid. Ordene pela data.', null, 'SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''paid'' ORDER BY order_date', array['order_number', 'status', 'total_amount'], array['orders'], null, null, 10, 'Filtros por status sao comuns em acompanhamentos de pedidos.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000315', '00000000-0000-0000-0000-000000000202', 'Pedidos a partir de 10 de fevereiro', 'pedidos-a-partir-10-fevereiro', 'free_select', 'easy', 'Liste numero, data e total dos pedidos feitos a partir de 2026-02-10. Ordene pela data.', null, 'SELECT order_number, order_date, total_amount FROM challenge_data.orders WHERE order_date >= ''2026-02-10'' ORDER BY order_date', array['order_number', 'order_date', 'total_amount'], array['orders'], null, null, 10, 'Comparacoes com datas funcionam como comparacoes de valores.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000316', '00000000-0000-0000-0000-000000000202', 'Baixo estoque', 'baixo-estoque', 'free_select', 'easy', 'Liste nome e estoque dos produtos com menos de 5 unidades. Ordene pelo estoque e depois pelo nome.', null, 'SELECT name, stock_quantity FROM challenge_data.products WHERE stock_quantity < 5 ORDER BY stock_quantity, name', array['name', 'stock_quantity'], array['products'], null, null, 10, 'O operador menor que ajuda a identificar prioridades de reposicao.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000317', '00000000-0000-0000-0000-000000000202', 'Pedidos com frete gratis', 'pedidos-frete-gratis', 'free_select', 'easy', 'Liste numero, total e frete dos pedidos com shipping_amount igual a zero. Ordene pelo numero.', null, 'SELECT order_number, total_amount, shipping_amount FROM challenge_data.orders WHERE shipping_amount = 0 ORDER BY order_number', array['order_number', 'total_amount', 'shipping_amount'], array['orders'], null, null, 10, 'Filtros numericos tambem podem usar igualdade.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000318', '00000000-0000-0000-0000-000000000202', 'Clientes fora de Rondonia', 'clientes-fora-rondonia', 'free_select', 'easy', 'Liste nome, cidade e estado dos clientes que nao moram em Rondonia. Ordene por estado e nome. Limite em 8.', null, 'SELECT full_name, city, state FROM challenge_data.customers WHERE state <> ''Rondonia'' ORDER BY state, full_name LIMIT 8', array['full_name', 'city', 'state'], array['customers'], null, null, 10, '<> seleciona valores diferentes do informado.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000319', '00000000-0000-0000-0000-000000000202', 'Pagamentos via pix aprovados', 'pagamentos-pix-aprovados', 'free_select', 'medium', 'Liste metodo, status, valor e data dos pagamentos por pix com status paid. Ordene pelo maior valor.', null, 'SELECT payment_method, status, amount, paid_at FROM challenge_data.payments WHERE payment_method = ''pix'' AND status = ''paid'' ORDER BY amount DESC', array['payment_method', 'status', 'amount', 'paid_at'], array['payments'], null, null, 20, 'AND exige que todos os filtros sejam verdadeiros.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000320', '00000000-0000-0000-0000-000000000202', 'Pedidos cancelados ou estornados', 'pedidos-cancelados-ou-estornados', 'free_select', 'medium', 'Liste numero, status e total dos pedidos com status cancelled ou refunded. Ordene por status e numero.', null, 'SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''cancelled'' OR status = ''refunded'' ORDER BY status, order_number', array['order_number', 'status', 'total_amount'], array['orders'], null, null, 20, 'OR aceita linhas que atendem a pelo menos uma condicao.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000321', '00000000-0000-0000-0000-000000000203', 'Clientes de estados selecionados', 'clientes-estados-selecionados', 'free_select', 'easy', 'Liste nome, cidade e estado dos clientes de SP, RJ ou MG. Ordene por estado e nome.', null, 'SELECT full_name, city, state FROM challenge_data.customers WHERE state IN (''SP'', ''RJ'', ''MG'') ORDER BY state, full_name', array['full_name', 'city', 'state'], array['customers'], null, null, 10, 'IN evita repetir varias comparacoes de igualdade.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000322', '00000000-0000-0000-0000-000000000203', 'Produtos entre 100 e 500', 'produtos-entre-100-500', 'free_select', 'easy', 'Liste nome e preco dos produtos com preco entre 100 e 500, inclusive. Ordene pelo preco e nome.', null, 'SELECT name, price FROM challenge_data.products WHERE price BETWEEN 100 AND 500 ORDER BY price, name', array['name', 'price'], array['products'], null, null, 10, 'BETWEEN inclui as duas pontas do intervalo.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000323', '00000000-0000-0000-0000-000000000203', 'Produtos com SQL no nome', 'produtos-com-sql-no-nome', 'free_select', 'easy', 'Liste nome, SKU e preco dos produtos cujo nome contem SQL. Ordene pelo nome.', null, 'SELECT name, sku, price FROM challenge_data.products WHERE name LIKE ''%SQL%'' ORDER BY name', array['name', 'sku', 'price'], array['products'], null, null, 10, 'LIKE com % procura trechos dentro de textos.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000324', '00000000-0000-0000-0000-000000000203', 'Produtos inativos ou sem estoque', 'produtos-inativos-ou-sem-estoque', 'free_select', 'medium', 'Liste nome, ativo e estoque dos produtos inativos ou com estoque zero. Ordene pelo nome.', null, 'SELECT name, active, stock_quantity FROM challenge_data.products WHERE active = false OR stock_quantity = 0 ORDER BY name', array['name', 'active', 'stock_quantity'], array['products'], null, null, 20, 'OR e util para unir dois criterios de alerta.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000325', '00000000-0000-0000-0000-000000000203', 'Pagamentos nao aprovados', 'pagamentos-nao-aprovados', 'free_select', 'medium', 'Liste metodo, status e valor dos pagamentos cujo status nao e paid. Ordene por status e maior valor.', null, 'SELECT payment_method, status, amount FROM challenge_data.payments WHERE status <> ''paid'' ORDER BY status, amount DESC', array['payment_method', 'status', 'amount'], array['payments'], null, null, 20, '<> tambem funciona com textos.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000326', '00000000-0000-0000-0000-000000000203', 'Entregas sem data final', 'entregas-sem-data-final', 'free_select', 'medium', 'Liste transportadora, status e data de envio das entregas sem delivered_at. Ordene pela data de envio.', null, 'SELECT carrier, status, shipped_at FROM challenge_data.shipments WHERE delivered_at IS NULL ORDER BY shipped_at', array['carrier', 'status', 'shipped_at'], array['shipments'], null, null, 20, 'IS NULL encontra valores ausentes.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000327', '00000000-0000-0000-0000-000000000203', 'Entregas finalizadas', 'entregas-finalizadas', 'free_select', 'medium', 'Liste transportadora e delivered_at das entregas com delivered_at preenchido. Ordene pela entrega e limite em 5.', null, 'SELECT carrier, delivered_at FROM challenge_data.shipments WHERE delivered_at IS NOT NULL ORDER BY delivered_at LIMIT 5', array['carrier', 'delivered_at'], array['shipments'], null, null, 20, 'IS NOT NULL remove registros sem valor na coluna.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000328', '00000000-0000-0000-0000-000000000203', 'Produtos ativos de preco medio', 'produtos-ativos-preco-medio', 'free_select', 'medium', 'Liste nome, preco e estoque dos produtos ativos com preco entre 200 e 1000. Ordene pelo preco.', null, 'SELECT name, price, stock_quantity FROM challenge_data.products WHERE active = true AND price >= 200 AND price <= 1000 ORDER BY price', array['name', 'price', 'stock_quantity'], array['products'], null, null, 20, 'AND permite combinar varios limites de negocio.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000329', '00000000-0000-0000-0000-000000000203', 'Clientes que comecam com A ou B', 'clientes-comecam-a-ou-b', 'free_select', 'medium', 'Liste nome, email e estado dos clientes cujo nome comeca com A ou B. Ordene pelo nome.', null, 'SELECT full_name, email, state FROM challenge_data.customers WHERE full_name LIKE ''A%'' OR full_name LIKE ''B%'' ORDER BY full_name', array['full_name', 'email', 'state'], array['customers'], null, null, 20, 'LIKE ''A%'' procura textos que iniciam com a letra A.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000330', '00000000-0000-0000-0000-000000000203', 'Pedidos validos da primeira semana', 'pedidos-validos-primeira-semana', 'free_select', 'hard', 'Liste numero, status e data dos pedidos entre 2026-02-01 e 2026-02-07 que nao foram cancelados. Ordene pela data.', null, 'SELECT order_number, status, order_date FROM challenge_data.orders WHERE order_date BETWEEN ''2026-02-01'' AND ''2026-02-07 23:59:59'' AND status <> ''cancelled'' ORDER BY order_date', array['order_number', 'status', 'order_date'], array['orders'], null, null, 35, 'BETWEEN, AND e <> juntos formam filtros de periodo com exclusao.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000331', '00000000-0000-0000-0000-000000000204', 'Top 3 produtos mais caros', 'top-3-produtos-mais-caros', 'free_select', 'easy', 'Liste nome e preco dos 3 produtos mais caros.', null, 'SELECT name, price FROM challenge_data.products ORDER BY price DESC LIMIT 3', array['name', 'price'], array['products'], null, null, 10, 'DESC coloca maiores valores no topo.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000332', '00000000-0000-0000-0000-000000000204', 'Cinco produtos mais baratos ativos', 'cinco-produtos-mais-baratos-ativos', 'free_select', 'easy', 'Liste nome e preco dos 5 produtos ativos mais baratos.', null, 'SELECT name, price FROM challenge_data.products WHERE active = true ORDER BY price ASC LIMIT 5', array['name', 'price'], array['products'], null, null, 10, 'ASC e a ordem crescente, util para rankings de menor valor.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000333', '00000000-0000-0000-0000-000000000204', 'Quatro clientes mais novos', 'quatro-clientes-mais-novos', 'free_select', 'easy', 'Liste nome e data de cadastro dos 4 clientes mais novos.', null, 'SELECT full_name, created_at FROM challenge_data.customers ORDER BY created_at DESC LIMIT 4', array['full_name', 'created_at'], array['customers'], null, null, 10, 'Datas recentes aparecem primeiro com ORDER BY data DESC.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000334', '00000000-0000-0000-0000-000000000204', 'Maiores pedidos', 'maiores-pedidos', 'free_select', 'easy', 'Liste numero e total dos 5 pedidos de maior valor.', null, 'SELECT order_number, total_amount FROM challenge_data.orders ORDER BY total_amount DESC LIMIT 5', array['order_number', 'total_amount'], array['orders'], null, null, 10, 'Rankings numericos precisam de ORDER BY e LIMIT.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000335', '00000000-0000-0000-0000-000000000204', 'Pedidos por status e data', 'pedidos-por-status-data', 'free_select', 'medium', 'Liste numero, status e data dos pedidos. Ordene por status crescente e data decrescente. Limite em 10.', null, 'SELECT order_number, status, order_date FROM challenge_data.orders ORDER BY status ASC, order_date DESC LIMIT 10', array['order_number', 'status', 'order_date'], array['orders'], null, null, 20, 'Cada coluna do ORDER BY pode ter sua propria direcao.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000336', '00000000-0000-0000-0000-000000000204', 'Prioridade de estoque', 'prioridade-de-estoque', 'free_select', 'medium', 'Liste nome, estoque e preco dos produtos. Ordene pelo menor estoque e, em empate, maior preco. Limite em 8.', null, 'SELECT name, stock_quantity, price FROM challenge_data.products ORDER BY stock_quantity ASC, price DESC LIMIT 8', array['name', 'stock_quantity', 'price'], array['products'], null, null, 20, 'Ordenacoes compostas ajudam a transformar dados em filas de acao.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000337', '00000000-0000-0000-0000-000000000204', 'Pagamentos recentes', 'pagamentos-recentes', 'free_select', 'medium', 'Liste metodo, valor e data dos pagamentos com paid_at preenchido. Ordene do mais recente para o mais antigo e limite em 6.', null, 'SELECT payment_method, amount, paid_at FROM challenge_data.payments WHERE paid_at IS NOT NULL ORDER BY paid_at DESC LIMIT 6', array['payment_method', 'amount', 'paid_at'], array['payments'], null, null, 20, 'Filtrar nulos antes de ordenar evita datas vazias no ranking.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000338', '00000000-0000-0000-0000-000000000204', 'Entregas por conclusao', 'entregas-por-conclusao', 'free_select', 'medium', 'Liste transportadora, status e delivered_at das entregas finalizadas. Ordene pela data de entrega e limite em 5.', null, 'SELECT carrier, status, delivered_at FROM challenge_data.shipments WHERE delivered_at IS NOT NULL ORDER BY delivered_at LIMIT 5', array['carrier', 'status', 'delivered_at'], array['shipments'], null, null, 20, 'ORDER BY em datas tambem pode ser combinado com LIMIT.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000339', '00000000-0000-0000-0000-000000000204', 'Segunda pagina de produtos caros', 'segunda-pagina-produtos-caros', 'free_select', 'hard', 'Liste nome e preco dos produtos ordenados por preco decrescente. Pule os 3 primeiros e retorne os proximos 5.', null, 'SELECT name, price FROM challenge_data.products ORDER BY price DESC LIMIT 5 OFFSET 3', array['name', 'price'], array['products'], null, null, 35, 'OFFSET pula linhas antes de aplicar o recorte final.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000340', '00000000-0000-0000-0000-000000000204', 'Ranking por margem', 'ranking-por-margem', 'free_select', 'hard', 'Liste nome e margem dos produtos usando price - cost como margin. Ordene por margin decrescente e nome. Limite em 5.', null, 'SELECT name, price - cost AS margin FROM challenge_data.products ORDER BY margin DESC, name LIMIT 5', array['name', 'margin'], array['products'], null, null, 35, 'Aliases calculados podem ser usados no ORDER BY.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000341', '00000000-0000-0000-0000-000000000205', 'Clientes por estado', 'clientes-por-estado', 'free_select', 'medium', 'Conte clientes por estado usando customer_count como alias. Ordene pela maior contagem e depois pelo estado.', null, 'SELECT state, count(*) AS customer_count FROM challenge_data.customers GROUP BY state ORDER BY customer_count DESC, state', array['state', 'customer_count'], array['customers'], null, null, 20, 'GROUP BY cria um grupo para cada estado antes da contagem.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000342', '00000000-0000-0000-0000-000000000205', 'Pedidos por status', 'pedidos-por-status', 'free_select', 'medium', 'Conte pedidos por status usando order_count como alias. Ordene por maior contagem e status.', null, 'SELECT status, count(*) AS order_count FROM challenge_data.orders GROUP BY status ORDER BY order_count DESC, status', array['status', 'order_count'], array['orders'], null, null, 20, 'COUNT(*) resume quantas linhas existem em cada grupo.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000343', '00000000-0000-0000-0000-000000000205', 'Valor total por status', 'valor-total-por-status', 'free_select', 'medium', 'Some total_amount por status dos pedidos usando total_amount_sum como alias. Ordene pelo maior total.', null, 'SELECT status, sum(total_amount) AS total_amount_sum FROM challenge_data.orders GROUP BY status ORDER BY total_amount_sum DESC', array['status', 'total_amount_sum'], array['orders'], null, null, 20, 'SUM agrega valores numericos por categoria.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000344', '00000000-0000-0000-0000-000000000205', 'Resumo por produto ativo', 'resumo-por-produto-ativo', 'free_select', 'medium', 'Agrupe produtos por active, conte linhas e calcule preco medio como average_price. Ordene com ativos primeiro.', null, 'SELECT active, count(*) AS product_count, avg(price) AS average_price FROM challenge_data.products GROUP BY active ORDER BY active DESC', array['active', 'product_count', 'average_price'], array['products'], null, null, 20, 'AVG calcula medias e pode ser combinado com COUNT.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000345', '00000000-0000-0000-0000-000000000205', 'Faixa de precos', 'faixa-de-precos', 'free_select', 'medium', 'Retorne o menor preco como min_price e o maior preco como max_price da tabela products.', null, 'SELECT min(price) AS min_price, max(price) AS max_price FROM challenge_data.products', array['min_price', 'max_price'], array['products'], null, null, 20, 'MIN e MAX resumem extremos sem precisar ordenar a tabela.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000346', '00000000-0000-0000-0000-000000000205', 'Estoque por situacao', 'estoque-por-situacao', 'free_select', 'medium', 'Some o estoque por active usando total_stock como alias. Ordene com ativos primeiro.', null, 'SELECT active, sum(stock_quantity) AS total_stock FROM challenge_data.products GROUP BY active ORDER BY active DESC', array['active', 'total_stock'], array['products'], null, null, 20, 'Agregacoes tambem funcionam sobre colunas inteiras.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000347', '00000000-0000-0000-0000-000000000205', 'Transacoes por tipo', 'transacoes-por-tipo', 'free_select', 'medium', 'Some amount por type em financial_transactions usando total_amount. Ordene pelo maior total.', null, 'SELECT type, sum(amount) AS total_amount FROM challenge_data.financial_transactions GROUP BY type ORDER BY total_amount DESC', array['type', 'total_amount'], array['financial_transactions'], null, null, 20, 'Agrupar transacoes por tipo separa receita, taxa, frete e estorno.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000348', '00000000-0000-0000-0000-000000000205', 'Pagamentos por metodo', 'pagamentos-por-metodo', 'free_select', 'medium', 'Agrupe pagamentos por metodo, contando payment_count e somando total_amount. Ordene pelo maior total.', null, 'SELECT payment_method, count(*) AS payment_count, sum(amount) AS total_amount FROM challenge_data.payments GROUP BY payment_method ORDER BY total_amount DESC', array['payment_method', 'payment_count', 'total_amount'], array['payments'], null, null, 20, 'Varios agregadores podem aparecer no mesmo SELECT.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000349', '00000000-0000-0000-0000-000000000205', 'Pedidos por dia', 'pedidos-por-dia', 'free_select', 'hard', 'Agrupe pedidos por order_date::date como order_day e conte order_count. Ordene pelo dia.', null, 'SELECT order_date::date AS order_day, count(*) AS order_count FROM challenge_data.orders GROUP BY order_day ORDER BY order_day', array['order_day', 'order_count'], array['orders'], null, null, 35, 'Converter timestamp para date permite agrupar por dia calendario.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000350', '00000000-0000-0000-0000-000000000205', 'Status com volume', 'status-com-volume', 'free_select', 'hard', 'Liste status com pelo menos 3 pedidos usando HAVING. Retorne status e order_count, ordenando pela maior contagem.', null, 'SELECT status, count(*) AS order_count FROM challenge_data.orders GROUP BY status HAVING count(*) >= 3 ORDER BY order_count DESC, status', array['status', 'order_count'], array['orders'], null, null, 35, 'HAVING filtra grupos depois que a agregacao foi calculada.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000351', '00000000-0000-0000-0000-000000000206', 'Produtos com categoria', 'produtos-com-categoria', 'free_select', 'medium', 'Liste produto, categoria e preco usando JOIN entre products e categories. Ordene por categoria e produto.', null, 'SELECT p.name AS product_name, c.name AS category_name, p.price FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id ORDER BY category_name, product_name', array['product_name', 'category_name', 'price'], array['products', 'categories'], null, null, 20, 'JOIN conecta linhas quando a chave estrangeira encontra a chave primaria.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000352', '00000000-0000-0000-0000-000000000206', 'Pedidos com cliente', 'pedidos-com-cliente', 'free_select', 'medium', 'Liste numero do pedido, cliente e total usando JOIN entre orders e customers. Ordene pela data e limite em 10.', null, 'SELECT o.order_number, c.full_name, o.total_amount FROM challenge_data.orders o JOIN challenge_data.customers c ON c.id = o.customer_id ORDER BY o.order_date LIMIT 10', array['order_number', 'full_name', 'total_amount'], array['orders', 'customers'], null, null, 20, 'A tabela orders guarda o customer_id, que aponta para customers.id.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000353', '00000000-0000-0000-0000-000000000206', 'Itens com produto', 'itens-com-produto', 'free_select', 'medium', 'Liste produto, quantidade e total da linha usando JOIN entre order_items e products. Ordene pelo maior line_total e limite em 10.', null, 'SELECT p.name AS product_name, oi.quantity, oi.line_total FROM challenge_data.order_items oi JOIN challenge_data.products p ON p.id = oi.product_id ORDER BY oi.line_total DESC LIMIT 10', array['product_name', 'quantity', 'line_total'], array['order_items', 'products'], null, null, 20, 'JOIN tambem permite enriquecer itens com nomes de produtos.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000354', '00000000-0000-0000-0000-000000000206', 'Pagamentos com pedido', 'pagamentos-com-pedido', 'free_select', 'medium', 'Liste numero do pedido, metodo, status do pagamento e valor. Ordene pelo numero do pedido.', null, 'SELECT o.order_number, p.payment_method, p.status, p.amount FROM challenge_data.payments p JOIN challenge_data.orders o ON o.id = p.order_id ORDER BY o.order_number', array['order_number', 'payment_method', 'status', 'amount'], array['payments', 'orders'], null, null, 20, 'Pagamentos se relacionam a pedidos por order_id.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000355', '00000000-0000-0000-0000-000000000206', 'Entregas com pedido', 'entregas-com-pedido', 'free_select', 'medium', 'Liste numero do pedido, transportadora e status da entrega. Ordene pelo numero.', null, 'SELECT o.order_number, s.carrier, s.status FROM challenge_data.shipments s JOIN challenge_data.orders o ON o.id = s.order_id ORDER BY o.order_number', array['order_number', 'carrier', 'status'], array['shipments', 'orders'], null, null, 20, 'A tabela shipments descreve a logistica ligada ao pedido.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000356', '00000000-0000-0000-0000-000000000206', 'Pedidos de clientes de SP', 'pedidos-clientes-sp', 'free_select', 'medium', 'Liste cliente, numero do pedido e status para clientes de SP. Ordene por cliente e pedido.', null, 'SELECT c.full_name, o.order_number, o.status FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE c.state = ''SP'' ORDER BY c.full_name, o.order_number', array['full_name', 'order_number', 'status'], array['customers', 'orders'], null, null, 20, 'Filtros podem usar colunas de qualquer tabela ja unida.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000357', '00000000-0000-0000-0000-000000000206', 'Produtos de Informatica', 'produtos-de-informatica', 'free_select', 'medium', 'Liste categoria, produto e preco dos produtos da categoria Informatica. Ordene pelo produto.', null, 'SELECT c.name AS category_name, p.name AS product_name, p.price FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id WHERE c.name = ''Informatica'' ORDER BY product_name', array['category_name', 'product_name', 'price'], array['categories', 'products'], null, null, 20, 'JOIN permite filtrar por uma tabela e retornar dados de outra.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000358', '00000000-0000-0000-0000-000000000206', 'Pedidos entregues com cliente', 'pedidos-entregues-com-cliente', 'free_select', 'medium', 'Liste cliente, numero e status dos pedidos delivered. Ordene pelo cliente.', null, 'SELECT c.full_name, o.order_number, o.status FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.status = ''delivered'' ORDER BY c.full_name', array['full_name', 'order_number', 'status'], array['customers', 'orders'], null, null, 20, 'O status fica em orders, enquanto o nome do cliente fica em customers.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000359', '00000000-0000-0000-0000-000000000206', 'Itens do pedido A1001', 'itens-pedido-a1001', 'free_select', 'hard', 'Liste numero do pedido, produto, quantidade, preco unitario e total da linha para o pedido A1001. Ordene pelo produto.', null, 'SELECT o.order_number, p.name AS product_name, oi.quantity, oi.unit_price, oi.line_total FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_number = ''A1001'' ORDER BY product_name', array['order_number', 'product_name', 'quantity', 'unit_price', 'line_total'], array['orders', 'order_items', 'products'], null, null, 35, 'Dois JOINs levam do pedido aos itens e dos itens aos produtos.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000360', '00000000-0000-0000-0000-000000000206', 'Maiores pagamentos com cliente', 'maiores-pagamentos-com-cliente', 'free_select', 'hard', 'Liste cliente, pedido, metodo e valor dos pagamentos paid. Ordene pelo maior valor e limite em 8.', null, 'SELECT c.full_name, o.order_number, p.payment_method, p.amount FROM challenge_data.payments p JOIN challenge_data.orders o ON o.id = p.order_id JOIN challenge_data.customers c ON c.id = o.customer_id WHERE p.status = ''paid'' ORDER BY p.amount DESC LIMIT 8', array['full_name', 'order_number', 'payment_method', 'amount'], array['payments', 'orders', 'customers'], null, null, 35, 'JOINs em cadeia montam uma visao completa do pagamento.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000361', '00000000-0000-0000-0000-000000000207', 'Quantidade de pedidos por cliente', 'quantidade-pedidos-por-cliente', 'free_select', 'hard', 'Use LEFT JOIN para listar todos os clientes e sua order_count. Ordene pela maior contagem e depois pelo nome.', null, 'SELECT c.full_name, count(o.id) AS order_count FROM challenge_data.customers c LEFT JOIN challenge_data.orders o ON o.customer_id = c.id GROUP BY c.id, c.full_name ORDER BY order_count DESC, c.full_name', array['full_name', 'order_count'], array['customers', 'orders'], null, null, 35, 'LEFT JOIN preserva clientes mesmo quando nao ha pedidos.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000362', '00000000-0000-0000-0000-000000000207', 'Produtos nunca comprados', 'produtos-nunca-comprados', 'free_select', 'hard', 'Use LEFT JOIN para listar nome e SKU dos produtos que nao aparecem em order_items. Ordene pelo nome.', null, 'SELECT p.name, p.sku FROM challenge_data.products p LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id WHERE oi.id IS NULL ORDER BY p.name', array['name', 'sku'], array['products', 'order_items'], null, null, 35, 'LEFT JOIN com IS NULL encontra registros sem relacionamento.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000363', '00000000-0000-0000-0000-000000000207', 'Pedidos sem entrega', 'pedidos-sem-entrega', 'free_select', 'hard', 'Liste numero e status dos pedidos que ainda nao possuem registro em shipments. Ordene pelo numero.', null, 'SELECT o.order_number, o.status FROM challenge_data.orders o LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE s.id IS NULL ORDER BY o.order_number', array['order_number', 'status'], array['orders', 'shipments'], null, null, 35, 'Nem todo pedido tem entrega; LEFT JOIN revela essa ausencia.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000364', '00000000-0000-0000-0000-000000000207', 'Vendas por categoria', 'vendas-por-categoria', 'free_select', 'hard', 'Some line_total por categoria como sales_total. Ordene pelo maior total.', null, 'SELECT c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.name ORDER BY sales_total DESC', array['category_name', 'sales_total'], array['categories', 'products', 'order_items'], null, null, 35, 'Agregacoes depois de JOINs calculam metricas por dimensao.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000365', '00000000-0000-0000-0000-000000000207', 'Clientes que mais compraram', 'clientes-que-mais-compraram', 'free_select', 'hard', 'Some total_amount por cliente apenas para pedidos paid, shipped ou delivered. Ordene pelo maior total e limite em 5.', null, 'SELECT c.full_name, sum(o.total_amount) AS total_spent FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY total_spent DESC LIMIT 5', array['full_name', 'total_spent'], array['customers', 'orders'], null, null, 35, 'O filtro evita somar pedidos cancelados, pendentes ou estornados.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000366', '00000000-0000-0000-0000-000000000207', 'Pedido, pagamento e entrega', 'pedido-pagamento-entrega', 'free_select', 'hard', 'Liste numero do pedido, payment_status e shipment_status usando JOIN em payments e LEFT JOIN em shipments. Ordene pelo numero e limite em 12.', null, 'SELECT o.order_number, p.status AS payment_status, s.status AS shipment_status FROM challenge_data.orders o JOIN challenge_data.payments p ON p.order_id = o.id LEFT JOIN challenge_data.shipments s ON s.order_id = o.id ORDER BY o.order_number LIMIT 12', array['order_number', 'payment_status', 'shipment_status'], array['orders', 'payments', 'shipments'], null, null, 35, 'LEFT JOIN mantem pagamentos mesmo quando a entrega ainda nao existe.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000367', '00000000-0000-0000-0000-000000000207', 'Financeiro por cliente e tipo', 'financeiro-por-cliente-tipo', 'free_select', 'hard', 'Some amount por cliente e tipo de transacao. Retorne full_name, type e total_amount. Ordene por cliente e tipo.', null, 'SELECT c.full_name, ft.type, sum(ft.amount) AS total_amount FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id GROUP BY c.full_name, ft.type ORDER BY c.full_name, ft.type', array['full_name', 'type', 'total_amount'], array['customers', 'orders', 'financial_transactions'], null, null, 35, 'Relatorios financeiros geralmente cruzam cliente, pedido e transacao.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000368', '00000000-0000-0000-0000-000000000207', 'Unidades vendidas por produto', 'unidades-vendidas-por-produto', 'free_select', 'hard', 'Some quantity por produto como units_sold. Ordene pelo maior volume e nome. Limite em 8.', null, 'SELECT p.name, sum(oi.quantity) AS units_sold FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY p.id, p.name ORDER BY units_sold DESC, p.name LIMIT 8', array['name', 'units_sold'], array['products', 'order_items'], null, null, 35, 'Somar quantidades mede giro, nao faturamento.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000369', '00000000-0000-0000-0000-000000000207', 'Ticket medio por estado', 'ticket-medio-por-estado', 'free_select', 'hard', 'Calcule average_order_value e order_count por estado do cliente. Ordene pelo maior ticket medio.', null, 'SELECT c.state, avg(o.total_amount) AS average_order_value, count(o.id) AS order_count FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id GROUP BY c.state ORDER BY average_order_value DESC', array['state', 'average_order_value', 'order_count'], array['customers', 'orders'], null, null, 35, 'AVG depois do JOIN permite analisar comportamento regional.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000370', '00000000-0000-0000-0000-000000000207', 'Margem estimada por categoria', 'margem-estimada-por-categoria', 'free_select', 'hard', 'Calcule estimated_margin por categoria usando sum((price - cost) * quantity). Ordene pela maior margem.', null, 'SELECT c.name AS category_name, sum((p.price - p.cost) * oi.quantity) AS estimated_margin FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.name ORDER BY estimated_margin DESC', array['category_name', 'estimated_margin'], array['categories', 'products', 'order_items'], null, null, 35, 'Expressoes agregadas permitem estimar indicadores de negocio.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000371', '00000000-0000-0000-0000-000000000208', 'CTE de produtos ativos', 'cte-produtos-ativos', 'free_select', 'medium', 'Crie a CTE active_products com produtos ativos e retorne nome e preco dos 5 mais caros.', null, 'WITH active_products AS (SELECT name, price, stock_quantity FROM challenge_data.products WHERE active = true) SELECT name, price FROM active_products ORDER BY price DESC LIMIT 5', array['name', 'price'], array['products'], null, null, 20, 'CTEs nomeiam uma etapa intermediaria da consulta.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000372', '00000000-0000-0000-0000-000000000208', 'CTE de pedidos pagos', 'cte-pedidos-pagos', 'free_select', 'medium', 'Crie a CTE paid_orders com pedidos paid e retorne numero e total ordenados pelo maior total.', null, 'WITH paid_orders AS (SELECT order_number, total_amount FROM challenge_data.orders WHERE status = ''paid'') SELECT order_number, total_amount FROM paid_orders ORDER BY total_amount DESC', array['order_number', 'total_amount'], array['orders'], null, null, 20, 'A consulta final le a CTE como se fosse uma tabela temporaria.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000373', '00000000-0000-0000-0000-000000000208', 'CTE de pedidos com cliente', 'cte-pedidos-com-cliente', 'free_select', 'hard', 'Crie uma CTE customer_orders com cliente, pedido e total. Retorne somente totais a partir de 1000, ordenados pelo maior total.', null, 'WITH customer_orders AS (SELECT c.full_name, o.order_number, o.total_amount FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id) SELECT full_name, order_number, total_amount FROM customer_orders WHERE total_amount >= 1000 ORDER BY total_amount DESC', array['full_name', 'order_number', 'total_amount'], array['customers', 'orders'], null, null, 35, 'CTEs ajudam a separar o JOIN do filtro final.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000374', '00000000-0000-0000-0000-000000000208', 'CTE de vendas por categoria', 'cte-vendas-por-categoria', 'free_select', 'hard', 'Crie sales_by_category com categoria e sales_total. Retorne categorias com sales_total maior que 1000.', null, 'WITH sales_by_category AS (SELECT c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.name) SELECT category_name, sales_total FROM sales_by_category WHERE sales_total > 1000 ORDER BY sales_total DESC', array['category_name', 'sales_total'], array['categories', 'products', 'order_items'], null, null, 35, 'A CTE permite filtrar uma agregacao usando um SELECT externo.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000375', '00000000-0000-0000-0000-000000000208', 'CTE de baixo estoque', 'cte-baixo-estoque', 'free_select', 'medium', 'Crie low_stock com produtos de estoque menor ou igual a 5 e retorne nome e estoque ordenados por estoque e nome.', null, 'WITH low_stock AS (SELECT name, stock_quantity FROM challenge_data.products WHERE stock_quantity <= 5) SELECT name, stock_quantity FROM low_stock ORDER BY stock_quantity, name', array['name', 'stock_quantity'], array['products'], null, null, 20, 'CTEs simples tambem melhoram a leitura de filtros importantes.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000376', '00000000-0000-0000-0000-000000000208', 'CTE de pedidos recentes', 'cte-pedidos-recentes', 'free_select', 'medium', 'Crie recent_orders com pedidos a partir de 2026-02-10 e retorne numero, data e total ordenados pela data.', null, 'WITH recent_orders AS (SELECT order_number, order_date, total_amount FROM challenge_data.orders WHERE order_date >= ''2026-02-10'') SELECT order_number, order_date, total_amount FROM recent_orders ORDER BY order_date', array['order_number', 'order_date', 'total_amount'], array['orders'], null, null, 20, 'Separar o periodo em uma CTE facilita revisar a regra.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000377', '00000000-0000-0000-0000-000000000208', 'Duas CTEs para pedidos entregues', 'duas-ctes-pedidos-entregues', 'free_select', 'hard', 'Crie delivered_orders e depois delivered_customers. Retorne cliente, pedido e total de pedidos delivered ordenados pelo cliente.', null, 'WITH delivered_orders AS (SELECT id, customer_id, order_number, total_amount FROM challenge_data.orders WHERE status = ''delivered''), delivered_customers AS (SELECT c.full_name, d.order_number, d.total_amount FROM delivered_orders d JOIN challenge_data.customers c ON c.id = d.customer_id) SELECT full_name, order_number, total_amount FROM delivered_customers ORDER BY full_name', array['full_name', 'order_number', 'total_amount'], array['orders', 'customers'], null, null, 35, 'CTEs encadeadas criam uma narrativa clara para a consulta.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000378', '00000000-0000-0000-0000-000000000208', 'CTE de totais por metodo', 'cte-totais-por-metodo', 'free_select', 'hard', 'Crie method_totals com soma de pagamentos por metodo. Retorne metodos com total_amount >= 1000.', null, 'WITH method_totals AS (SELECT payment_method, sum(amount) AS total_amount FROM challenge_data.payments GROUP BY payment_method) SELECT payment_method, total_amount FROM method_totals WHERE total_amount >= 1000 ORDER BY total_amount DESC', array['payment_method', 'total_amount'], array['payments'], null, null, 35, 'Uma CTE agregada pode ser filtrada pelo SELECT externo.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000379', '00000000-0000-0000-0000-000000000208', 'CTE de margem de produto', 'cte-margem-produto', 'free_select', 'hard', 'Crie product_margins com name e margin. Retorne produtos com margin maior que 200 ordenados pela maior margem.', null, 'WITH product_margins AS (SELECT name, price - cost AS margin FROM challenge_data.products) SELECT name, margin FROM product_margins WHERE margin > 200 ORDER BY margin DESC', array['name', 'margin'], array['products'], null, null, 35, 'A CTE permite reutilizar um alias calculado no filtro externo.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000380', '00000000-0000-0000-0000-000000000208', 'CTE com ranking de pedidos', 'cte-ranking-pedidos', 'free_select', 'hard', 'Crie ranked_orders com row_number por total decrescente. Retorne ranking, pedido e total dos 5 maiores.', null, 'WITH ranked_orders AS (SELECT order_number, total_amount, row_number() OVER (ORDER BY total_amount DESC) AS ranking FROM challenge_data.orders) SELECT ranking, order_number, total_amount FROM ranked_orders WHERE ranking <= 5 ORDER BY ranking', array['ranking', 'order_number', 'total_amount'], array['orders'], null, null, 35, 'Window functions podem ser isoladas em CTEs para filtrar o ranking depois.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000381', '00000000-0000-0000-0000-000000000209', 'Clientes de SP ou RJ com UNION', 'clientes-sp-rj-union', 'free_select', 'medium', 'Use UNION para unir clientes de SP e clientes de RJ. Retorne full_name e state, ordenando pelo nome.', null, 'SELECT full_name, state FROM challenge_data.customers WHERE state = ''SP'' UNION SELECT full_name, state FROM challenge_data.customers WHERE state = ''RJ'' ORDER BY full_name', array['full_name', 'state'], array['customers'], null, null, 20, 'UNION combina resultados compativeis e remove duplicidades.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000382', '00000000-0000-0000-0000-000000000209', 'Produtos ativos e inativos rotulados', 'produtos-ativos-inativos-rotulados', 'free_select', 'medium', 'Use UNION ALL para listar produtos ativos e inativos com product_status igual a active ou inactive. Ordene por status e nome.', null, 'SELECT name, ''active'' AS product_status FROM challenge_data.products WHERE active = true UNION ALL SELECT name, ''inactive'' AS product_status FROM challenge_data.products WHERE active = false ORDER BY product_status, name', array['name', 'product_status'], array['products'], null, null, 20, 'UNION ALL preserva todas as linhas sem tentar remover repeticoes.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000383', '00000000-0000-0000-0000-000000000209', 'Pedidos pagos e entregues', 'pedidos-pagos-entregues-union', 'free_select', 'medium', 'Use UNION para combinar pedidos paid e delivered. Retorne order_number e status, ordenando por status e numero.', null, 'SELECT order_number, status FROM challenge_data.orders WHERE status = ''paid'' UNION SELECT order_number, status FROM challenge_data.orders WHERE status = ''delivered'' ORDER BY status, order_number', array['order_number', 'status'], array['orders'], null, null, 20, 'As duas partes do UNION precisam retornar colunas compativeis.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000384', '00000000-0000-0000-0000-000000000209', 'Linha do tempo de pedidos e pagamentos', 'linha-tempo-pedidos-pagamentos', 'free_select', 'hard', 'Use UNION ALL para unir pedidos e pagamentos antes de 2026-02-05. Retorne reference, event_type e event_at ordenados por event_at.', null, 'SELECT order_number AS reference, ''order'' AS event_type, order_date AS event_at FROM challenge_data.orders WHERE order_date < ''2026-02-05'' UNION ALL SELECT payment_method AS reference, ''payment'' AS event_type, paid_at AS event_at FROM challenge_data.payments WHERE paid_at < ''2026-02-05'' AND paid_at IS NOT NULL ORDER BY event_at, event_type', array['reference', 'event_type', 'event_at'], array['orders', 'payments'], null, null, 35, 'UNION ALL pode criar uma linha do tempo quando as colunas sao padronizadas.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000385', '00000000-0000-0000-0000-000000000209', 'Categorias e produtos premium', 'categorias-produtos-premium', 'free_select', 'medium', 'Use UNION ALL para unir nomes de categorias e produtos com preco >= 1000. Retorne name e source, ordenando por source e name.', null, 'SELECT name, ''category'' AS source FROM challenge_data.categories UNION ALL SELECT name, ''product'' AS source FROM challenge_data.products WHERE price >= 1000 ORDER BY source, name', array['name', 'source'], array['categories', 'products'], null, null, 20, 'Colunas literais ajudam a identificar a origem de cada linha.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000386', '00000000-0000-0000-0000-000000000209', 'Receitas e estornos', 'receitas-e-estornos', 'free_select', 'medium', 'Use UNION ALL para unir transacoes revenue e refund. Retorne order_id, type e amount, ordenando por type e maior amount.', null, 'SELECT order_id, type, amount FROM challenge_data.financial_transactions WHERE type = ''revenue'' UNION ALL SELECT order_id, type, amount FROM challenge_data.financial_transactions WHERE type = ''refund'' ORDER BY type, amount DESC', array['order_id', 'type', 'amount'], array['financial_transactions'], null, null, 20, 'UNION ALL permite comparar tipos de movimento lado a lado.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000387', '00000000-0000-0000-0000-000000000209', 'Busca combinada por nome', 'busca-combinada-por-nome', 'free_select', 'hard', 'Use UNION ALL para retornar clientes com Silva no nome e produtos com SQL no nome. Use result_name e result_type. Ordene por tipo e nome.', null, 'SELECT full_name AS result_name, ''customer'' AS result_type FROM challenge_data.customers WHERE full_name LIKE ''%Silva%'' UNION ALL SELECT name AS result_name, ''product'' AS result_type FROM challenge_data.products WHERE name LIKE ''%SQL%'' ORDER BY result_type, result_name', array['result_name', 'result_type'], array['customers', 'products'], null, null, 35, 'UNION pode montar resultados de busca com origem padronizada.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000388', '00000000-0000-0000-0000-000000000209', 'Clientes do Norte e Sudeste', 'clientes-norte-sudeste', 'free_select', 'medium', 'Use UNION ALL para rotular clientes de Rondonia ou AM como norte e clientes de SP, RJ ou MG como sudeste. Ordene por region e nome.', null, 'SELECT full_name, state, ''norte'' AS region FROM challenge_data.customers WHERE state IN (''Rondonia'', ''AM'') UNION ALL SELECT full_name, state, ''sudeste'' AS region FROM challenge_data.customers WHERE state IN (''SP'', ''RJ'', ''MG'') ORDER BY region, full_name', array['full_name', 'state', 'region'], array['customers'], null, null, 20, 'A mesma tabela pode aparecer nos dois lados do UNION com filtros diferentes.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000389', '00000000-0000-0000-0000-000000000209', 'Contagens de metodos e status', 'contagens-metodos-status', 'free_select', 'hard', 'Use UNION ALL para juntar contagens por payment_method e por status de pedidos. Retorne label, source e total. Ordene por source e label.', null, 'SELECT payment_method AS label, ''payment_method'' AS source, count(*) AS total FROM challenge_data.payments GROUP BY payment_method UNION ALL SELECT status AS label, ''order_status'' AS source, count(*) AS total FROM challenge_data.orders GROUP BY status ORDER BY source, label', array['label', 'source', 'total'], array['payments', 'orders'], null, null, 35, 'Agregacoes tambem podem ser unidas quando possuem a mesma estrutura.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000390', '00000000-0000-0000-0000-000000000209', 'UNION dentro de CTE', 'union-dentro-de-cte', 'free_select', 'hard', 'Crie selected_orders com UNION ALL entre pedidos total_amount >= 2000 e pedidos pending. Retorne numero, status e total ordenados pelo maior total.', null, 'WITH selected_orders AS (SELECT order_number, status, total_amount FROM challenge_data.orders WHERE total_amount >= 2000 UNION ALL SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''pending'') SELECT order_number, status, total_amount FROM selected_orders ORDER BY total_amount DESC', array['order_number', 'status', 'total_amount'], array['orders'], null, null, 35, 'CTE e UNION juntos deixam a combinacao mais facil de revisar.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000391', '00000000-0000-0000-0000-000000000210', 'Top clientes por gasto valido', 'top-clientes-gasto-valido', 'free_select', 'hard', 'Com uma CTE valid_orders, some pedidos paid, shipped e delivered por cliente. Retorne os 5 maiores totais.', null, 'WITH valid_orders AS (SELECT customer_id, total_amount FROM challenge_data.orders WHERE status IN (''paid'', ''shipped'', ''delivered'')) SELECT c.full_name, sum(v.total_amount) AS total_spent FROM valid_orders v JOIN challenge_data.customers c ON c.id = v.customer_id GROUP BY c.full_name ORDER BY total_spent DESC LIMIT 5', array['full_name', 'total_spent'], array['orders', 'customers'], null, null, 35, 'A CTE isola a regra de pedido valido antes da agregacao por cliente.', array['select'], 1, true),
  ('00000000-0000-0000-0000-000000000392', '00000000-0000-0000-0000-000000000210', 'Produtos acima da media da categoria', 'produtos-acima-media-categoria', 'free_select', 'hard', 'Crie category_avg com media de preco por categoria e liste produtos com preco acima da media da propria categoria.', null, 'WITH category_avg AS (SELECT category_id, avg(price) AS average_price FROM challenge_data.products GROUP BY category_id) SELECT p.name, p.price, a.average_price FROM challenge_data.products p JOIN category_avg a ON a.category_id = p.category_id WHERE p.price > a.average_price ORDER BY p.price DESC', array['name', 'price', 'average_price'], array['products'], null, null, 35, 'Comparar com medias por grupo exige calcular o grupo antes de filtrar o item.', array['select'], 2, true),
  ('00000000-0000-0000-0000-000000000393', '00000000-0000-0000-0000-000000000210', 'Clientes sem pedido entregue', 'clientes-sem-pedido-entregue', 'free_select', 'hard', 'Use LEFT JOIN contra pedidos delivered para listar clientes sem pedido entregue. Retorne full_name e state, ordenando pelo nome.', null, 'SELECT c.full_name, c.state FROM challenge_data.customers c LEFT JOIN challenge_data.orders o ON o.customer_id = c.id AND o.status = ''delivered'' WHERE o.id IS NULL ORDER BY c.full_name', array['full_name', 'state'], array['customers', 'orders'], null, null, 35, 'O filtro de status no ON preserva clientes que nao possuem pedido entregue.', array['select'], 3, true),
  ('00000000-0000-0000-0000-000000000394', '00000000-0000-0000-0000-000000000210', 'Pedidos pagos ainda sem entrega', 'pedidos-pagos-sem-entrega', 'free_select', 'hard', 'Liste pedidos paid que nao possuem shipment. Retorne order_number, total_amount e status, ordenando pelo maior total.', null, 'SELECT o.order_number, o.total_amount, o.status FROM challenge_data.orders o LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.status = ''paid'' AND s.id IS NULL ORDER BY o.total_amount DESC', array['order_number', 'total_amount', 'status'], array['orders', 'shipments'], null, null, 35, 'LEFT JOIN com filtro combina status financeiro e ausencia logistica.', array['select'], 4, true),
  ('00000000-0000-0000-0000-000000000395', '00000000-0000-0000-0000-000000000210', 'Estoque e venda por categoria', 'estoque-venda-por-categoria', 'free_select', 'hard', 'Use CTEs para calcular total_stock e sales_total por categoria sem duplicar estoque. Ordene pelo maior sales_total.', null, 'WITH category_stock AS (SELECT c.id, c.name AS category_name, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.id, c.name), category_sales AS (SELECT c.id, coalesce(sum(oi.line_total), 0) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.id) SELECT cs.category_name, cs.total_stock, s.sales_total FROM category_stock cs JOIN category_sales s ON s.id = cs.id ORDER BY s.sales_total DESC', array['category_name', 'total_stock', 'sales_total'], array['categories', 'products', 'order_items'], null, null, 35, 'Separar estoque e vendas evita multiplicar estoque pelo numero de itens vendidos.', array['select'], 5, true),
  ('00000000-0000-0000-0000-000000000396', '00000000-0000-0000-0000-000000000210', 'Pedidos com desconto ou frete gratis', 'pedidos-desconto-ou-frete-gratis', 'free_select', 'medium', 'Use UNION para combinar pedidos com desconto e pedidos com frete gratis. Retorne order_number, reason e amount, ordenando por reason e numero.', null, 'SELECT order_number, ''discount'' AS reason, discount_amount AS amount FROM challenge_data.orders WHERE discount_amount > 0 UNION SELECT order_number, ''free_shipping'' AS reason, shipping_amount AS amount FROM challenge_data.orders WHERE shipping_amount = 0 ORDER BY reason, order_number', array['order_number', 'reason', 'amount'], array['orders'], null, null, 20, 'UNION ajuda a produzir listas de motivos com regras diferentes.', array['select'], 6, true),
  ('00000000-0000-0000-0000-000000000397', '00000000-0000-0000-0000-000000000210', 'Eventos recentes de pedido', 'eventos-recentes-pedido', 'free_select', 'hard', 'Crie uma CTE events com UNION ALL entre pedidos e pagamentos. Retorne eventos a partir de 2026-02-18 ordenados por data.', null, 'WITH events AS (SELECT order_number AS reference, ''order'' AS event_type, order_date AS event_at FROM challenge_data.orders UNION ALL SELECT payment_method AS reference, ''payment'' AS event_type, paid_at AS event_at FROM challenge_data.payments WHERE paid_at IS NOT NULL) SELECT reference, event_type, event_at FROM events WHERE event_at >= ''2026-02-18'' ORDER BY event_at, event_type', array['reference', 'event_type', 'event_at'], array['orders', 'payments'], null, null, 35, 'UNION em CTE cria uma base comum para filtros finais.', array['select'], 7, true),
  ('00000000-0000-0000-0000-000000000398', '00000000-0000-0000-0000-000000000210', 'Produtos vendidos em pedidos nao cancelados', 'produtos-vendidos-pedidos-nao-cancelados', 'free_select', 'hard', 'Some quantity por produto considerando pedidos que nao sejam cancelled. Ordene por units_sold desc e nome.', null, 'SELECT p.name, sum(oi.quantity) AS units_sold FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.status <> ''cancelled'' GROUP BY p.name ORDER BY units_sold DESC, p.name', array['name', 'units_sold'], array['products', 'order_items', 'orders'], null, null, 35, 'Filtrar pedidos antes da agregacao muda o volume vendido.', array['select'], 8, true),
  ('00000000-0000-0000-0000-000000000399', '00000000-0000-0000-0000-000000000210', 'Resultado financeiro liquido por pedido', 'resultado-financeiro-liquido-pedido', 'free_select', 'hard', 'Calcule net_amount por pedido: revenue soma positivo; refund, fee e shipping_cost subtraem. Ordene pelo maior net_amount.', null, 'SELECT o.order_number, sum(CASE WHEN ft.type IN (''refund'', ''fee'', ''shipping_cost'') THEN -ft.amount ELSE ft.amount END) AS net_amount FROM challenge_data.orders o JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id GROUP BY o.order_number ORDER BY net_amount DESC', array['order_number', 'net_amount'], array['orders', 'financial_transactions'], null, null, 35, 'CASE transforma tipos de transacao em sinal positivo ou negativo.', array['select'], 9, true),
  ('00000000-0000-0000-0000-000000000400', '00000000-0000-0000-0000-000000000210', 'Desafio final de categorias', 'desafio-final-categorias', 'free_select', 'special', 'Com CTEs category_sales e category_stock, retorne category_name, sales_total e total_stock para categorias com sales_total > 500. Ordene pelo maior sales_total.', null, 'WITH category_sales AS (SELECT c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.name), category_stock AS (SELECT c.name AS category_name, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.name) SELECT s.category_name, s.sales_total, st.total_stock FROM category_sales s JOIN category_stock st ON st.category_name = s.category_name WHERE s.sales_total > 500 ORDER BY s.sales_total DESC', array['category_name', 'sales_total', 'total_stock'], array['categories', 'products', 'order_items'], null, null, 80, 'O desafio combina CTEs, JOIN, agregacao, filtro e ordenacao em uma consulta final.', array['select'], 10, true),
  ('00000000-0000-0000-0000-000000000401', '00000000-0000-0000-0000-000000000211', 'Inserindo categoria de cursos', 'inserindo-categoria-cursos', 'insert_rows', 'easy', 'Insira uma categoria chamada Cursos usando o id 20000000-0000-0000-0000-000000000090.', null, 'INSERT INTO categories (id, name) VALUES (''20000000-0000-0000-0000-000000000090'', ''Cursos'')', array['id', 'name'], array['categories'], null, 'SELECT id::text, name FROM categories WHERE id = ''20000000-0000-0000-0000-000000000090''', 10, 'INSERT adiciona uma linha nova informando colunas e valores na mesma ordem.', array['insert_rows'], 1, true),
  ('00000000-0000-0000-0000-000000000402', '00000000-0000-0000-0000-000000000211', 'Inserindo novo cliente', 'inserindo-novo-cliente', 'insert_rows', 'medium', 'Insira a cliente Laura Gomes, email laura@exemplo.com, cidade Boa Vista e estado RR usando o id 10000000-0000-0000-0000-000000000090.', null, 'INSERT INTO customers (id, full_name, email, city, state) VALUES (''10000000-0000-0000-0000-000000000090'', ''Laura Gomes'', ''laura@exemplo.com'', ''Boa Vista'', ''RR'')', array['id', 'full_name', 'email', 'city', 'state'], array['customers'], null, 'SELECT id::text, full_name, email, city, state FROM customers WHERE id = ''10000000-0000-0000-0000-000000000090''', 20, 'Declarar as colunas no INSERT deixa a operacao previsivel mesmo quando a tabela tem defaults.', array['insert_rows'], 2, true),
  ('00000000-0000-0000-0000-000000000403', '00000000-0000-0000-0000-000000000211', 'Inserindo multiplas categorias', 'inserindo-multiplas-categorias-sandbox', 'insert_rows', 'medium', 'Insira as categorias Audio e Video usando os ids 20000000-0000-0000-0000-000000000091 e 20000000-0000-0000-0000-000000000092.', null, 'INSERT INTO categories (id, name) VALUES (''20000000-0000-0000-0000-000000000091'', ''Audio''), (''20000000-0000-0000-0000-000000000092'', ''Video'')', array['id', 'name'], array['categories'], null, 'SELECT id::text, name FROM categories WHERE id IN (''20000000-0000-0000-0000-000000000091'', ''20000000-0000-0000-0000-000000000092'') ORDER BY id', 20, 'Um unico INSERT pode criar varias linhas separando os grupos de valores por virgula.', array['insert_rows'], 3, true),
  ('00000000-0000-0000-0000-000000000404', '00000000-0000-0000-0000-000000000211', 'Removendo produto inativo', 'removendo-produto-inativo', 'delete_rows', 'medium', 'Remova o produto WEB-FHD pelo SKU. Use DELETE com WHERE.', null, 'DELETE FROM products WHERE sku = ''WEB-FHD''', array['remaining_products'], array['products'], null, 'SELECT count(*)::int AS remaining_products FROM products WHERE sku = ''WEB-FHD''', 20, 'DELETE deve ser acompanhado de WHERE para remover apenas as linhas pretendidas.', array['delete_rows'], 4, true),
  ('00000000-0000-0000-0000-000000000405', '00000000-0000-0000-0000-000000000211', 'Removendo pagamentos falhos', 'removendo-pagamentos-falhos', 'delete_rows', 'medium', 'Remova todos os pagamentos com status failed.', null, 'DELETE FROM payments WHERE status = ''failed''', array['failed_payments'], array['payments'], null, 'SELECT count(*)::int AS failed_payments FROM payments WHERE status = ''failed''', 20, 'Filtros por status sao comuns em limpezas controladas de dados operacionais.', array['delete_rows'], 5, true),
  ('00000000-0000-0000-0000-000000000406', '00000000-0000-0000-0000-000000000211', 'Removendo pedidos pendentes', 'removendo-pedidos-pendentes', 'delete_rows', 'hard', 'Remova todos os pedidos com status pending.', null, 'DELETE FROM orders WHERE status = ''pending''', array['pending_orders'], array['orders'], null, 'SELECT count(*)::int AS pending_orders FROM orders WHERE status = ''pending''', 35, 'Mesmo em remocoes em lote, o WHERE precisa representar uma regra clara.', array['delete_rows'], 6, true),
  ('00000000-0000-0000-0000-000000000407', '00000000-0000-0000-0000-000000000211', 'Criando tabela de fornecedores', 'criando-tabela-fornecedores-sandbox', 'create_table', 'hard', 'Crie a tabela suppliers com id uuid primary key, name text not null, city text e active boolean default true.', null, 'CREATE TABLE suppliers (id uuid PRIMARY KEY, name text NOT NULL, city text, active boolean DEFAULT true)', array['column_name', 'data_type', 'is_nullable', 'column_default'], array['suppliers'], null, 'SELECT column_name, data_type, is_nullable, column_default FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = ''suppliers'' ORDER BY ordinal_position', 35, 'CREATE TABLE define colunas, tipos e restricoes antes de qualquer linha existir.', array['create_table'], 7, true),
  ('00000000-0000-0000-0000-000000000408', '00000000-0000-0000-0000-000000000211', 'Criando tabela de avaliacoes', 'criando-tabela-avaliacoes', 'create_table', 'hard', 'Crie a tabela product_reviews com id uuid primary key, product_id uuid not null, rating int not null e comment text.', null, 'CREATE TABLE product_reviews (id uuid PRIMARY KEY, product_id uuid NOT NULL, rating int NOT NULL, comment text)', array['column_name', 'data_type', 'is_nullable'], array['product_reviews'], null, 'SELECT column_name, data_type, is_nullable FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = ''product_reviews'' ORDER BY ordinal_position', 35, 'A modelagem minima de uma tabela combina chave primaria, campos obrigatorios e campos opcionais.', array['create_table'], 8, true),
  ('00000000-0000-0000-0000-000000000409', '00000000-0000-0000-0000-000000000211', 'Removendo tabela de importacao', 'removendo-tabela-importacao', 'drop_table', 'medium', 'Remova a tabela staging_imports.', null, 'DROP TABLE staging_imports', array['table_removed'], array['staging_imports'], 'CREATE TABLE staging_imports (id uuid PRIMARY KEY, raw_payload text NOT NULL)', 'SELECT (to_regclass(''staging_imports'') IS NULL) AS table_removed', 20, 'DROP TABLE remove a estrutura inteira; aqui isso acontece apenas no sandbox do desafio.', array['drop_table'], 9, true),
  ('00000000-0000-0000-0000-000000000410', '00000000-0000-0000-0000-000000000211', 'Removendo tabela temporaria', 'removendo-tabela-temporaria-sandbox', 'drop_table', 'hard', 'Remova a tabela temporary_reviews usando DROP TABLE IF EXISTS.', null, 'DROP TABLE IF EXISTS temporary_reviews', array['table_removed'], array['temporary_reviews'], 'CREATE TABLE temporary_reviews (id uuid PRIMARY KEY, notes text)', 'SELECT (to_regclass(''temporary_reviews'') IS NULL) AS table_removed', 35, 'IF EXISTS evita erro quando a tabela ja nao existe, sem mudar o objetivo do DROP.', array['drop_table'], 10, true),
  ('00000000-0000-0000-0000-000000000411', '00000000-0000-0000-0000-000000000212', 'Receita total no mes', 'negocio-receita-total-mes', 'free_select', 'medium', 'Pergunta de negocio: qual foi a receita total da loja em fevereiro de 2026? Retorne `revenue_total` somando `amount` das transacoes `revenue` em `financial_transactions` no periodo de 2026-02-01 ate antes de 2026-03-01.', null, 'SELECT sum(ft.amount) AS revenue_total FROM challenge_data.financial_transactions ft WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' AND ft.type = ''revenue''', array[]::text[], array['financial_transactions'], null, null, 20, 'Receita total usa apenas transacoes de receita dentro do periodo fechado.', array['select', 'draft'], 1, false),
  ('00000000-0000-0000-0000-000000000412', '00000000-0000-0000-0000-000000000212', 'Lucro liquido no mes', 'negocio-lucro-liquido-mes', 'free_select', 'medium', 'Pergunta de negocio: qual foi o lucro liquido da loja em fevereiro de 2026 considerando receitas positivas e `fee`, `shipping_cost` e `refund` como saidas? Retorne `net_profit`.', null, 'SELECT sum(CASE WHEN ft.type = ''revenue'' THEN ft.amount ELSE -ft.amount END) AS net_profit FROM challenge_data.financial_transactions ft WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01''', array[]::text[], array['financial_transactions'], null, null, 20, 'O CASE transforma custos, taxas e estornos em valores negativos antes da soma.', array['select', 'draft'], 2, false),
  ('00000000-0000-0000-0000-000000000413', '00000000-0000-0000-0000-000000000212', 'Pedidos validos por status', 'negocio-pedidos-validos-por-status', 'free_select', 'medium', 'Pergunta de negocio: quantos pedidos validos houve por status em fevereiro de 2026? Considere status `paid`, `shipped` e `delivered`. Retorne `status` e `order_count`, ordenando por `order_count` decrescente e depois por `status` crescente.', null, 'SELECT o.status, count(*) AS order_count FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY o.status ORDER BY order_count DESC, o.status', array[]::text[], array['orders'], null, null, 20, 'Agrupar por status mostra o volume operacional dos pedidos validos.', array['select', 'draft'], 3, false),
  ('00000000-0000-0000-0000-000000000414', '00000000-0000-0000-0000-000000000212', 'Ticket medio por status', 'negocio-ticket-medio-por-status', 'free_select', 'medium', 'Pergunta de negocio: qual foi o ticket medio dos pedidos por status em fevereiro de 2026? Retorne `status`, `order_count` e `average_order_value`, ordenando por `average_order_value` decrescente.', null, 'SELECT o.status, count(*) AS order_count, round(avg(o.total_amount), 2) AS average_order_value FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY o.status ORDER BY average_order_value DESC', array[]::text[], array['orders'], null, null, 20, 'AVG resume o valor medio dos pedidos por grupo de status.', array['select', 'draft'], 4, false),
  ('00000000-0000-0000-0000-000000000415', '00000000-0000-0000-0000-000000000212', 'Categorias com maior receita', 'negocio-categorias-maior-receita', 'free_select', 'medium', 'Pergunta de negocio: quais categorias mais venderam em fevereiro de 2026? Retorne `category_name` e `sales_total`, somando `order_items.line_total` de pedidos `paid`, `shipped` ou `delivered`, ordenando por `sales_total` decrescente.', null, 'SELECT c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY sales_total DESC', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 20, 'A receita por categoria vem dos itens vendidos conectados aos produtos e categorias.', array['select', 'draft'], 5, false),
  ('00000000-0000-0000-0000-000000000416', '00000000-0000-0000-0000-000000000212', 'Lucro bruto por categoria', 'negocio-lucro-bruto-por-categoria', 'free_select', 'medium', 'Pergunta de negocio: qual foi o lucro bruto estimado por categoria em fevereiro de 2026? Retorne `category_name` e `gross_profit`, usando `sum((price - cost) * quantity)` em pedidos validos, ordenando por `gross_profit` decrescente.', null, 'SELECT c.name AS category_name, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY gross_profit DESC', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 20, 'A margem bruta usa preco, custo e quantidade vendida por item.', array['select', 'draft'], 6, false),
  ('00000000-0000-0000-0000-000000000417', '00000000-0000-0000-0000-000000000212', 'Unidades vendidas por categoria', 'negocio-unidades-vendidas-categoria', 'free_select', 'medium', 'Pergunta de negocio: quais categorias venderam mais unidades em fevereiro de 2026? Retorne `category_name` e `units_sold`, somando `order_items.quantity` em pedidos validos, ordenando por `units_sold` decrescente e `category_name` crescente.', null, 'SELECT c.name AS category_name, sum(oi.quantity) AS units_sold FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY units_sold DESC, category_name', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 20, 'Quantidade vendida mede giro, diferente de faturamento.', array['select', 'draft'], 7, false),
  ('00000000-0000-0000-0000-000000000418', '00000000-0000-0000-0000-000000000212', 'Clientes que mais compraram', 'negocio-clientes-maior-gasto', 'free_select', 'medium', 'Pergunta de negocio: quais clientes mais compraram em fevereiro de 2026? Retorne `full_name` e `total_spent`, somando `orders.total_amount` de pedidos validos, ordenando por `total_spent` decrescente e limitando em 10.', null, 'SELECT c.full_name, sum(o.total_amount) AS total_spent FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY total_spent DESC LIMIT 10', array[]::text[], array['customers', 'orders'], null, null, 20, 'O ranking de clientes soma pedidos validos por cliente.', array['select', 'draft'], 8, false),
  ('00000000-0000-0000-0000-000000000419', '00000000-0000-0000-0000-000000000212', 'Receita por estado', 'negocio-receita-por-estado', 'free_select', 'medium', 'Pergunta de negocio: quais estados geraram mais receita em pedidos validos em fevereiro de 2026? Retorne `state` e `sales_total`, ordenando por `sales_total` decrescente.', null, 'SELECT c.state, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.state ORDER BY sales_total DESC', array[]::text[], array['customers', 'orders'], null, null, 20, 'Cruzar clientes e pedidos permite analisar receita por estado.', array['select', 'draft'], 9, false),
  ('00000000-0000-0000-0000-000000000420', '00000000-0000-0000-0000-000000000212', 'Receita por metodo de pagamento', 'negocio-receita-por-metodo-pagamento', 'free_select', 'medium', 'Pergunta de negocio: quais metodos de pagamento concentraram mais valor pago em fevereiro de 2026? Retorne `payment_method`, `payment_count` e `paid_total`, considerando apenas pagamentos `paid`, ordenando por `paid_total` decrescente.', null, 'SELECT p.payment_method, count(*) AS payment_count, sum(p.amount) AS paid_total FROM challenge_data.payments p WHERE p.paid_at >= TIMESTAMP ''2026-02-01'' AND p.paid_at < TIMESTAMP ''2026-03-01'' AND p.status = ''paid'' GROUP BY p.payment_method ORDER BY paid_total DESC', array[]::text[], array['payments'], null, null, 20, 'Pagamentos pagos por metodo mostram como a receita foi liquidada.', array['select', 'draft'], 10, false),
  ('00000000-0000-0000-0000-000000000421', '00000000-0000-0000-0000-000000000212', 'Pedidos com frete gratis', 'negocio-pedidos-com-frete-gratis', 'free_select', 'medium', 'Pergunta de negocio: quantos pedidos tiveram frete gratis em fevereiro de 2026? Retorne `free_shipping_orders` contando pedidos com `shipping_amount = 0`.', null, 'SELECT count(*) AS free_shipping_orders FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.shipping_amount = 0', array[]::text[], array['orders'], null, null, 20, 'Pedidos com frete zero indicam uso de promocao ou condicao comercial.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000422', '00000000-0000-0000-0000-000000000212', 'Descontos por dia', 'negocio-descontos-por-dia', 'free_select', 'medium', 'Pergunta de negocio: quanto desconto foi concedido por dia em fevereiro de 2026? Retorne `order_day` e `discount_total`, considerando apenas pedidos com desconto maior que zero, ordenando por `order_day` crescente.', null, 'SELECT o.order_date::date AS order_day, sum(o.discount_amount) AS discount_total FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.discount_amount > 0 GROUP BY order_day ORDER BY order_day', array[]::text[], array['orders'], null, null, 20, 'Agrupar por dia mostra quando os descontos foram usados.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000423', '00000000-0000-0000-0000-000000000212', 'Produtos com maior receita', 'negocio-produtos-maior-receita', 'free_select', 'medium', 'Pergunta de negocio: quais produtos geraram mais receita em pedidos validos de fevereiro de 2026? Retorne `product_name` e `sales_total`, ordenando por `sales_total` decrescente e limitando em 10.', null, 'SELECT p.name AS product_name, sum(oi.line_total) AS sales_total FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY p.id, p.name ORDER BY sales_total DESC LIMIT 10', array[]::text[], array['products', 'order_items', 'orders'], null, null, 20, 'Produto com maior receita usa soma de line_total em pedidos validos.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000424', '00000000-0000-0000-0000-000000000212', 'Produtos com maior lucro bruto', 'negocio-produtos-maior-lucro-bruto', 'free_select', 'medium', 'Pergunta de negocio: quais produtos tiveram maior lucro bruto estimado em fevereiro de 2026? Retorne `product_name` e `gross_profit`, usando `(price - cost) * quantity` em pedidos validos, ordenando por `gross_profit` decrescente.', null, 'SELECT p.name AS product_name, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY p.id, p.name ORDER BY gross_profit DESC', array[]::text[], array['products', 'order_items', 'orders'], null, null, 20, 'Lucro bruto por produto combina margem unitaria e quantidade vendida.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000425', '00000000-0000-0000-0000-000000000212', 'Receita diaria', 'negocio-receita-diaria', 'free_select', 'medium', 'Pergunta de negocio: qual foi a receita diaria de pedidos validos em fevereiro de 2026? Retorne `order_day` e `sales_total`, ordenando por `order_day` crescente.', null, 'SELECT o.order_date::date AS order_day, sum(o.total_amount) AS sales_total FROM challenge_data.orders o WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY order_day ORDER BY order_day', array[]::text[], array['orders'], null, null, 20, 'Receita diaria ajuda a acompanhar tendencia no periodo.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000426', '00000000-0000-0000-0000-000000000212', 'Transacoes por tipo', 'negocio-transacoes-por-tipo', 'free_select', 'medium', 'Pergunta de negocio: qual foi o total financeiro por tipo de transacao em fevereiro de 2026? Retorne `type`, `transaction_count` e `total_amount`, ordenando por `total_amount` decrescente.', null, 'SELECT ft.type, count(*) AS transaction_count, sum(ft.amount) AS total_amount FROM challenge_data.financial_transactions ft WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' GROUP BY ft.type ORDER BY total_amount DESC', array[]::text[], array['financial_transactions'], null, null, 20, 'O agrupamento por tipo separa receitas, taxas, fretes e estornos.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000427', '00000000-0000-0000-0000-000000000212', 'Entregas por transportadora', 'negocio-entregas-por-transportadora', 'free_select', 'medium', 'Pergunta de negocio: quantos pedidos entregues cada transportadora concluiu em fevereiro de 2026? Retorne `carrier` e `delivered_count`, considerando `shipments.status = ''delivered''`, ordenando por `delivered_count` decrescente.', null, 'SELECT s.carrier, count(*) AS delivered_count FROM challenge_data.shipments s WHERE s.delivered_at >= TIMESTAMP ''2026-02-01'' AND s.delivered_at < TIMESTAMP ''2026-03-01'' AND s.status = ''delivered'' GROUP BY s.carrier ORDER BY delivered_count DESC', array[]::text[], array['shipments'], null, null, 20, 'Contar entregas concluidas por transportadora mede desempenho logistico basico.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000428', '00000000-0000-0000-0000-000000000212', 'Pedidos sem pagamento aprovado', 'negocio-pedidos-sem-pagamento-aprovado', 'free_select', 'medium', 'Pergunta de negocio: quais pedidos de fevereiro de 2026 nao possuem pagamento `paid`? Retorne `order_number` e `status`, usando `LEFT JOIN` com pagamentos pagos, ordenando por `order_number` crescente.', null, 'SELECT o.order_number, o.status FROM challenge_data.orders o LEFT JOIN challenge_data.payments p ON p.order_id = o.id AND p.status = ''paid'' WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND p.id IS NULL ORDER BY o.order_number', array[]::text[], array['orders', 'payments'], null, null, 20, 'LEFT JOIN com IS NULL encontra pedidos sem pagamento aprovado.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000429', '00000000-0000-0000-0000-000000000212', 'Estoque por categoria', 'negocio-estoque-por-categoria', 'free_select', 'medium', 'Pergunta de negocio: qual e o estoque atual por categoria? Retorne `category_name`, `product_count` e `total_stock`, ordenando por `total_stock` decrescente.', null, 'SELECT c.name AS category_name, count(p.id) AS product_count, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.name ORDER BY total_stock DESC', array[]::text[], array['categories', 'products'], null, null, 20, 'Estoque por categoria cruza a dimensao categoria com produtos cadastrados.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000430', '00000000-0000-0000-0000-000000000212', 'Produtos ativos sem estoque', 'negocio-produtos-ativos-sem-estoque', 'free_select', 'medium', 'Pergunta de negocio: quais produtos ativos estao sem estoque? Retorne `category_name`, `product_name` e `stock_quantity`, filtrando `active = true` e `stock_quantity = 0`, ordenando por `category_name` e `product_name`.', null, 'SELECT c.name AS category_name, p.name AS product_name, p.stock_quantity FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id WHERE p.active = true AND p.stock_quantity = 0 ORDER BY category_name, product_name', array[]::text[], array['products', 'categories'], null, null, 20, 'Produtos ativos sem estoque indicam ruptura operacional.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000431', '00000000-0000-0000-0000-000000000212', 'Participacao da receita por categoria', 'negocio-participacao-receita-categoria', 'free_select', 'hard', 'Pergunta de negocio: qual a participacao percentual de cada categoria na receita valida de fevereiro de 2026? Retorne `category_name`, `sales_total` e `sales_share_pct`, ordenando por `sales_total` decrescente.', null, 'SELECT c.name AS category_name, sum(oi.line_total) AS sales_total, round(100 * sum(oi.line_total) / sum(sum(oi.line_total)) OVER (), 2) AS sales_share_pct FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY sales_total DESC', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'A janela sobre a soma agregada calcula participacao no total geral.', array['select', 'draft'], 21, false),
  ('00000000-0000-0000-0000-000000000432', '00000000-0000-0000-0000-000000000212', 'Lucro liquido por pedido', 'negocio-lucro-liquido-por-pedido', 'free_select', 'hard', 'Pergunta de negocio: qual foi o lucro liquido financeiro por pedido em fevereiro de 2026? Retorne `order_number`, `full_name` e `net_amount`, somando receitas positivas e demais tipos negativos, ordenando por `net_amount` decrescente.', null, 'SELECT o.order_number, c.full_name, sum(CASE WHEN ft.type = ''revenue'' THEN ft.amount ELSE -ft.amount END) AS net_amount FROM challenge_data.orders o JOIN challenge_data.customers c ON c.id = o.customer_id JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' GROUP BY o.order_number, c.full_name ORDER BY net_amount DESC', array[]::text[], array['orders', 'customers', 'financial_transactions'], null, null, 35, 'O lucro liquido por pedido vem das transacoes financeiras ligadas ao pedido.', array['select', 'draft'], 22, false),
  ('00000000-0000-0000-0000-000000000433', '00000000-0000-0000-0000-000000000212', 'Lucro bruto por cliente', 'negocio-lucro-bruto-por-cliente', 'free_select', 'hard', 'Pergunta de negocio: quais clientes geraram maior lucro bruto em pedidos validos de fevereiro de 2026? Retorne `full_name`, `order_count` e `gross_profit`, ordenando por `gross_profit` decrescente e limitando em 10.', null, 'SELECT c.full_name, count(DISTINCT o.id) AS order_count, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY gross_profit DESC LIMIT 10', array[]::text[], array['customers', 'orders', 'order_items', 'products'], null, null, 35, 'A margem bruta por cliente considera os itens comprados em pedidos validos.', array['select', 'draft'], 23, false),
  ('00000000-0000-0000-0000-000000000434', '00000000-0000-0000-0000-000000000212', 'Giro e margem por produto', 'negocio-giro-margem-produto', 'free_select', 'hard', 'Pergunta de negocio: quais produtos combinam maior giro e margem em fevereiro de 2026? Retorne `product_name`, `units_sold` e `gross_profit`, considerando pedidos validos, ordenando por `units_sold` decrescente e `gross_profit` decrescente.', null, 'SELECT p.name AS product_name, sum(oi.quantity) AS units_sold, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY p.id, p.name ORDER BY units_sold DESC, gross_profit DESC', array[]::text[], array['products', 'order_items', 'orders'], null, null, 35, 'Giro e margem juntos ajudam a priorizar produtos importantes.', array['select', 'draft'], 24, false),
  ('00000000-0000-0000-0000-000000000435', '00000000-0000-0000-0000-000000000212', 'Estoque e vendas por categoria', 'negocio-estoque-vendas-categoria', 'free_select', 'hard', 'Pergunta de negocio: compare estoque atual e vendas por categoria em fevereiro de 2026. Retorne `category_name`, `total_stock` e `sales_total`, usando CTEs `category_stock` e `category_sales`, ordenando por `sales_total` decrescente.', null, 'WITH category_stock AS (SELECT c.id, c.name AS category_name, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.id, c.name), category_sales AS (SELECT c.id, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id) SELECT cs.category_name, cs.total_stock, coalesce(s.sales_total, 0) AS sales_total FROM category_stock cs LEFT JOIN category_sales s ON s.id = cs.id ORDER BY sales_total DESC', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'Separar estoque e vendas em CTEs evita multiplicar estoque por item vendido.', array['select', 'draft'], 25, false),
  ('00000000-0000-0000-0000-000000000436', '00000000-0000-0000-0000-000000000212', 'Funil pagamento entrega', 'negocio-funil-pagamento-entrega', 'free_select', 'hard', 'Pergunta de negocio: como os pedidos de fevereiro de 2026 se distribuem entre status do pedido, pagamento e entrega? Retorne `order_status`, `payment_status`, `shipment_status` e `order_count`, ordenando por `order_count` decrescente.', null, 'SELECT o.status AS order_status, p.status AS payment_status, coalesce(s.status, ''sem_entrega'') AS shipment_status, count(*) AS order_count FROM challenge_data.orders o LEFT JOIN challenge_data.payments p ON p.order_id = o.id LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY o.status, p.status, coalesce(s.status, ''sem_entrega'') ORDER BY order_count DESC', array[]::text[], array['orders', 'payments', 'shipments'], null, null, 35, 'O funil combina tres estados operacionais do pedido.', array['select', 'draft'], 26, false),
  ('00000000-0000-0000-0000-000000000437', '00000000-0000-0000-0000-000000000212', 'Pedidos validos sem entrega', 'negocio-pedidos-validos-sem-entrega', 'free_select', 'hard', 'Pergunta de negocio: quais pedidos validos de fevereiro de 2026 ainda nao possuem entrega registrada? Retorne `order_number`, `status` e `total_amount`, usando LEFT JOIN com `shipments`, ordenando por `total_amount` decrescente.', null, 'SELECT o.order_number, o.status, o.total_amount FROM challenge_data.orders o LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') AND s.id IS NULL ORDER BY o.total_amount DESC', array[]::text[], array['orders', 'shipments'], null, null, 35, 'LEFT JOIN revela pedidos validos que ainda nao entraram no fluxo logistico.', array['select', 'draft'], 27, false),
  ('00000000-0000-0000-0000-000000000438', '00000000-0000-0000-0000-000000000212', 'Pagamentos pagos por dia e metodo', 'negocio-pagamentos-dia-metodo', 'free_select', 'hard', 'Pergunta de negocio: qual valor pago por dia e metodo em fevereiro de 2026? Retorne `payment_day`, `payment_method`, `payment_count` e `paid_total`, considerando `payments.status = ''paid''`, ordenando por `payment_day` e `paid_total` decrescente.', null, 'SELECT p.paid_at::date AS payment_day, p.payment_method, count(*) AS payment_count, sum(p.amount) AS paid_total FROM challenge_data.payments p WHERE p.paid_at >= TIMESTAMP ''2026-02-01'' AND p.paid_at < TIMESTAMP ''2026-03-01'' AND p.status = ''paid'' GROUP BY payment_day, p.payment_method ORDER BY payment_day, paid_total DESC', array[]::text[], array['payments'], null, null, 35, 'A visao por dia e metodo ajuda a conciliar recebimentos.', array['select', 'draft'], 28, false),
  ('00000000-0000-0000-0000-000000000439', '00000000-0000-0000-0000-000000000212', 'Estornos por cliente', 'negocio-estornos-por-cliente', 'free_select', 'hard', 'Pergunta de negocio: quais clientes tiveram maior valor estornado em fevereiro de 2026? Retorne `full_name`, `refund_count` e `refund_total`, considerando transacoes `refund`, ordenando por `refund_total` decrescente.', null, 'SELECT c.full_name, count(*) AS refund_count, sum(ft.amount) AS refund_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' AND ft.type = ''refund'' GROUP BY c.id, c.full_name ORDER BY refund_total DESC', array[]::text[], array['customers', 'orders', 'financial_transactions'], null, null, 35, 'Estornos por cliente cruzam transacoes financeiras com pedidos e clientes.', array['select', 'draft'], 29, false),
  ('00000000-0000-0000-0000-000000000440', '00000000-0000-0000-0000-000000000212', 'Ranking de estados por receita', 'negocio-ranking-estados-receita', 'free_select', 'hard', 'Pergunta de negocio: gere o ranking dos estados por receita valida em fevereiro de 2026. Retorne `state_rank`, `state` e `sales_total`, usando `rank()` por `sales_total` decrescente.', null, 'SELECT rank() OVER (ORDER BY sum(o.total_amount) DESC) AS state_rank, c.state, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.state ORDER BY state_rank, c.state', array[]::text[], array['customers', 'orders'], null, null, 35, 'A funcao de janela ranqueia os estados apos a agregacao.', array['select', 'draft'], 30, false),
  ('00000000-0000-0000-0000-000000000441', '00000000-0000-0000-0000-000000000212', 'Compra media por cliente ativo', 'negocio-compra-media-cliente-ativo', 'free_select', 'hard', 'Pergunta de negocio: qual o gasto medio por pedido dos clientes com pedidos validos em fevereiro de 2026? Retorne `full_name`, `order_count`, `total_spent` e `average_order_value`, ordenando por `average_order_value` decrescente.', null, 'SELECT c.full_name, count(o.id) AS order_count, sum(o.total_amount) AS total_spent, round(avg(o.total_amount), 2) AS average_order_value FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY average_order_value DESC', array[]::text[], array['customers', 'orders'], null, null, 35, 'A media por pedido identifica clientes de ticket mais alto.', array['select', 'draft'], 31, false),
  ('00000000-0000-0000-0000-000000000442', '00000000-0000-0000-0000-000000000212', 'Produtos acima da media da categoria', 'negocio-produtos-acima-media-categoria', 'free_select', 'hard', 'Pergunta de negocio: quais produtos ativos tem preco acima da media da propria categoria? Use uma CTE `category_average`. Retorne `category_name`, `product_name`, `price` e `average_price`, ordenando por `category_name` e `price` decrescente.', null, 'WITH category_average AS (SELECT category_id, round(avg(price), 2) AS average_price FROM challenge_data.products WHERE active = true GROUP BY category_id) SELECT c.name AS category_name, p.name AS product_name, p.price, ca.average_price FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id JOIN category_average ca ON ca.category_id = p.category_id WHERE p.active = true AND p.price > ca.average_price ORDER BY category_name, p.price DESC', array[]::text[], array['products', 'categories'], null, null, 35, 'Comparar produto com media da categoria exige uma etapa agregada antes do filtro.', array['select', 'draft'], 32, false),
  ('00000000-0000-0000-0000-000000000443', '00000000-0000-0000-0000-000000000212', 'Preco medio e margem media por categoria', 'negocio-preco-margem-media-categoria', 'free_select', 'hard', 'Pergunta de negocio: qual o preco medio e a margem media dos produtos ativos por categoria? Retorne `category_name`, `active_products`, `average_price` e `average_margin`, ordenando por `average_margin` decrescente.', null, 'SELECT c.name AS category_name, count(p.id) AS active_products, round(avg(p.price), 2) AS average_price, round(avg(p.price - p.cost), 2) AS average_margin FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id WHERE p.active = true GROUP BY c.name ORDER BY average_margin DESC', array[]::text[], array['categories', 'products'], null, null, 35, 'A margem media de cadastro usa preco menos custo em produtos ativos.', array['select', 'draft'], 33, false),
  ('00000000-0000-0000-0000-000000000444', '00000000-0000-0000-0000-000000000212', 'Margem bruta por dia', 'negocio-margem-bruta-por-dia', 'free_select', 'hard', 'Pergunta de negocio: qual foi a margem bruta estimada por dia em pedidos validos de fevereiro de 2026? Retorne `order_day`, `sales_total` e `gross_profit`, ordenando por `order_day` crescente.', null, 'SELECT o.order_date::date AS order_day, sum(oi.line_total) AS sales_total, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY order_day ORDER BY order_day', array[]::text[], array['orders', 'order_items', 'products'], null, null, 35, 'Margem diaria combina dados de pedido com os itens vendidos.', array['select', 'draft'], 34, false),
  ('00000000-0000-0000-0000-000000000445', '00000000-0000-0000-0000-000000000212', 'Clientes novos com pedido', 'negocio-clientes-novos-com-pedido', 'free_select', 'hard', 'Pergunta de negocio: quais clientes cadastrados em janeiro de 2026 fizeram pedidos validos em fevereiro de 2026? Retorne `full_name`, `created_at`, `order_count` e `total_spent`, ordenando por `total_spent` decrescente.', null, 'SELECT c.full_name, c.created_at, count(o.id) AS order_count, sum(o.total_amount) AS total_spent FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE c.created_at >= TIMESTAMP ''2026-01-01'' AND c.created_at < TIMESTAMP ''2026-02-01'' AND o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name, c.created_at ORDER BY total_spent DESC', array[]::text[], array['customers', 'orders'], null, null, 35, 'Cruzar data de cadastro com pedidos mede ativacao de clientes novos.', array['select', 'draft'], 35, false),
  ('00000000-0000-0000-0000-000000000446', '00000000-0000-0000-0000-000000000212', 'Tempo medio de entrega por transportadora', 'negocio-tempo-medio-entrega-transportadora', 'free_select', 'hard', 'Pergunta de negocio: qual o tempo medio de entrega em dias por transportadora para entregas concluidas em fevereiro de 2026? Retorne `carrier`, `delivered_count` e `average_delivery_days`, ordenando por `average_delivery_days` crescente.', null, 'SELECT s.carrier, count(*) AS delivered_count, round(avg(extract(epoch FROM (s.delivered_at - s.shipped_at)) / 86400), 2) AS average_delivery_days FROM challenge_data.shipments s WHERE s.delivered_at >= TIMESTAMP ''2026-02-01'' AND s.delivered_at < TIMESTAMP ''2026-03-01'' AND s.shipped_at IS NOT NULL AND s.delivered_at IS NOT NULL GROUP BY s.carrier ORDER BY average_delivery_days', array[]::text[], array['shipments'], null, null, 35, 'A diferenca entre entrega e envio convertida em dias mede prazo medio.', array['select', 'draft'], 36, false),
  ('00000000-0000-0000-0000-000000000447', '00000000-0000-0000-0000-000000000212', 'Falhas de pagamento por status do pedido', 'negocio-falhas-pagamento-status-pedido', 'free_select', 'hard', 'Pergunta de negocio: quais status de pedido concentram pagamentos falhos em fevereiro de 2026? Retorne `order_status`, `failed_payments` e `failed_amount`, considerando `payments.status = ''failed''`, ordenando por `failed_amount` decrescente.', null, 'SELECT o.status AS order_status, count(p.id) AS failed_payments, sum(p.amount) AS failed_amount FROM challenge_data.orders o JOIN challenge_data.payments p ON p.order_id = o.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND p.status = ''failed'' GROUP BY o.status ORDER BY failed_amount DESC', array[]::text[], array['orders', 'payments'], null, null, 35, 'Pagamentos falhos ligados ao status do pedido ajudam a identificar perdas.', array['select', 'draft'], 37, false),
  ('00000000-0000-0000-0000-000000000448', '00000000-0000-0000-0000-000000000212', 'Clientes com pedidos pagos e cancelados', 'negocio-clientes-pagos-cancelados', 'free_select', 'hard', 'Pergunta de negocio: quais clientes tiveram pedidos pagos ou entregues e tambem pedidos cancelados ou estornados em fevereiro de 2026? Retorne `full_name`, `valid_orders` e `problem_orders`, ordenando por `problem_orders` decrescente.', null, 'SELECT c.full_name, count(*) FILTER (WHERE o.status IN (''paid'', ''shipped'', ''delivered'')) AS valid_orders, count(*) FILTER (WHERE o.status IN (''cancelled'', ''refunded'')) AS problem_orders FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY c.id, c.full_name HAVING count(*) FILTER (WHERE o.status IN (''paid'', ''shipped'', ''delivered'')) > 0 AND count(*) FILTER (WHERE o.status IN (''cancelled'', ''refunded'')) > 0 ORDER BY problem_orders DESC, c.full_name', array[]::text[], array['customers', 'orders'], null, null, 35, 'FILTER permite contar subconjuntos de status dentro do mesmo agrupamento.', array['select', 'draft'], 38, false),
  ('00000000-0000-0000-0000-000000000449', '00000000-0000-0000-0000-000000000212', 'Categorias sem venda valida', 'negocio-categorias-sem-venda-valida', 'free_select', 'hard', 'Pergunta de negocio: quais categorias nao tiveram venda em pedidos validos de fevereiro de 2026? Retorne `category_name` e `valid_sales_total`, usando LEFT JOIN, ordenando por `category_name`.', null, 'SELECT c.name AS category_name, coalesce(sum(CASE WHEN o.id IS NOT NULL THEN oi.line_total ELSE 0 END), 0) AS valid_sales_total FROM challenge_data.categories c LEFT JOIN challenge_data.products p ON p.category_id = c.id LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id LEFT JOIN challenge_data.orders o ON o.id = oi.order_id AND o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name HAVING coalesce(sum(CASE WHEN o.id IS NOT NULL THEN oi.line_total ELSE 0 END), 0) = 0 ORDER BY category_name', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'LEFT JOIN preserva categorias mesmo sem pedidos validos no periodo.', array['select', 'draft'], 39, false),
  ('00000000-0000-0000-0000-000000000450', '00000000-0000-0000-0000-000000000212', 'Lucro por status ativo do produto', 'negocio-lucro-por-status-produto', 'free_select', 'hard', 'Pergunta de negocio: quanto lucro bruto veio de produtos ativos versus inativos em pedidos validos de fevereiro de 2026? Retorne `product_active`, `sales_total` e `gross_profit`, ordenando por `gross_profit` decrescente.', null, 'SELECT p.active AS product_active, sum(oi.line_total) AS sales_total, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY p.active ORDER BY gross_profit DESC', array[]::text[], array['products', 'order_items', 'orders'], null, null, 35, 'Agrupar por flag ativo mostra quanto a carteira vigente contribui.', array['select', 'draft'], 40, false),
  ('00000000-0000-0000-0000-000000000451', '00000000-0000-0000-0000-000000000212', 'Ranking de pedidos por lucro bruto', 'negocio-ranking-pedidos-lucro-bruto', 'free_select', 'hard', 'Pergunta de negocio: quais pedidos validos tiveram maior lucro bruto estimado em fevereiro de 2026? Retorne `profit_rank`, `order_number` e `gross_profit`, usando `rank()` e limitando em 10.', null, 'SELECT rank() OVER (ORDER BY sum((p.price - p.cost) * oi.quantity) DESC) AS profit_rank, o.order_number, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY o.id, o.order_number ORDER BY profit_rank, o.order_number LIMIT 10', array[]::text[], array['orders', 'order_items', 'products'], null, null, 35, 'Ranking por lucro bruto destaca pedidos de maior contribuicao.', array['select', 'draft'], 41, false),
  ('00000000-0000-0000-0000-000000000452', '00000000-0000-0000-0000-000000000212', 'Receita por grupo de entrega', 'negocio-receita-grupo-entrega', 'free_select', 'hard', 'Pergunta de negocio: quanto de receita valida de fevereiro de 2026 esta em pedidos com entrega e sem entrega? Retorne `delivery_group`, `order_count` e `sales_total`, usando LEFT JOIN com `shipments`, ordenando por `sales_total` decrescente.', null, 'SELECT CASE WHEN s.id IS NULL THEN ''sem_entrega'' ELSE ''com_entrega'' END AS delivery_group, count(DISTINCT o.id) AS order_count, sum(o.total_amount) AS sales_total FROM challenge_data.orders o LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY delivery_group ORDER BY sales_total DESC', array[]::text[], array['orders', 'shipments'], null, null, 35, 'O CASE classifica pedidos conforme existencia de registro logistico.', array['select', 'draft'], 42, false),
  ('00000000-0000-0000-0000-000000000453', '00000000-0000-0000-0000-000000000212', 'Estornos por dia', 'negocio-estornos-por-dia', 'free_select', 'hard', 'Pergunta de negocio: qual foi o valor estornado por dia em fevereiro de 2026? Retorne `refund_day`, `refund_count` e `refund_total`, ordenando por `refund_day` crescente.', null, 'SELECT ft.transaction_date AS refund_day, count(*) AS refund_count, sum(ft.amount) AS refund_total FROM challenge_data.financial_transactions ft WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' AND ft.type = ''refund'' GROUP BY ft.transaction_date ORDER BY refund_day', array[]::text[], array['financial_transactions'], null, null, 35, 'Agrupar estornos por dia mostra concentracao de reversoes.', array['select', 'draft'], 43, false),
  ('00000000-0000-0000-0000-000000000454', '00000000-0000-0000-0000-000000000212', 'Taxa de aprovacao por metodo', 'negocio-taxa-aprovacao-metodo', 'free_select', 'hard', 'Pergunta de negocio: qual a taxa de aprovacao por metodo de pagamento para pedidos de fevereiro de 2026? Retorne `payment_method`, `total_payments`, `paid_payments` e `paid_rate_pct`, ordenando por `paid_rate_pct` decrescente.', null, 'SELECT p.payment_method, count(*) AS total_payments, count(*) FILTER (WHERE p.status = ''paid'') AS paid_payments, round(100.0 * count(*) FILTER (WHERE p.status = ''paid'') / count(*), 2) AS paid_rate_pct FROM challenge_data.payments p JOIN challenge_data.orders o ON o.id = p.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY p.payment_method ORDER BY paid_rate_pct DESC, p.payment_method', array[]::text[], array['payments', 'orders'], null, null, 35, 'A taxa divide pagamentos pagos pelo total observado por metodo.', array['select', 'draft'], 44, false),
  ('00000000-0000-0000-0000-000000000455', '00000000-0000-0000-0000-000000000212', 'Vendas por categoria e estado', 'negocio-vendas-categoria-estado', 'free_select', 'hard', 'Pergunta de negocio: quais categorias vendem mais por estado em pedidos validos de fevereiro de 2026? Retorne `state`, `category_name` e `sales_total`, ordenando por `state` crescente e `sales_total` decrescente.', null, 'SELECT cu.state, c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.customers cu JOIN challenge_data.orders o ON o.customer_id = cu.id JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id JOIN challenge_data.categories c ON c.id = p.category_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY cu.state, c.name ORDER BY cu.state, sales_total DESC', array[]::text[], array['customers', 'orders', 'order_items', 'products', 'categories'], null, null, 35, 'Esse relatorio cruza geografia do cliente com categoria do produto.', array['select', 'draft'], 45, false),
  ('00000000-0000-0000-0000-000000000456', '00000000-0000-0000-0000-000000000212', 'Frete cobrado por estado', 'negocio-frete-cobrado-por-estado', 'free_select', 'hard', 'Pergunta de negocio: quanto frete foi cobrado por estado em pedidos validos de fevereiro de 2026? Retorne `state`, `order_count`, `shipping_total` e `sales_total`, ordenando por `shipping_total` decrescente.', null, 'SELECT c.state, count(o.id) AS order_count, sum(o.shipping_amount) AS shipping_total, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.state ORDER BY shipping_total DESC', array[]::text[], array['customers', 'orders'], null, null, 35, 'Frete por estado ajuda a avaliar custo e politica comercial por regiao.', array['select', 'draft'], 46, false),
  ('00000000-0000-0000-0000-000000000457', '00000000-0000-0000-0000-000000000212', 'Baixo estoque com alto giro', 'negocio-baixo-estoque-alto-giro', 'free_select', 'hard', 'Pergunta de negocio: quais produtos venderam pelo menos 2 unidades em fevereiro de 2026 e tem estoque atual menor que 5? Retorne `product_name`, `stock_quantity` e `units_sold`, ordenando por `units_sold` decrescente.', null, 'SELECT p.name AS product_name, p.stock_quantity, sum(oi.quantity) AS units_sold FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') AND p.stock_quantity < 5 GROUP BY p.id, p.name, p.stock_quantity HAVING sum(oi.quantity) >= 2 ORDER BY units_sold DESC', array[]::text[], array['products', 'order_items', 'orders'], null, null, 35, 'Combinar giro e estoque identifica risco de ruptura.', array['select', 'draft'], 47, false),
  ('00000000-0000-0000-0000-000000000458', '00000000-0000-0000-0000-000000000212', 'Pedidos com desconto e margem', 'negocio-pedidos-desconto-margem', 'free_select', 'hard', 'Pergunta de negocio: quais pedidos com desconto tiveram maior margem bruta em fevereiro de 2026? Retorne `order_number`, `discount_amount` e `gross_profit`, considerando pedidos validos com `discount_amount > 0`, ordenando por `gross_profit` decrescente.', null, 'SELECT o.order_number, o.discount_amount, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') AND o.discount_amount > 0 GROUP BY o.id, o.order_number, o.discount_amount ORDER BY gross_profit DESC', array[]::text[], array['orders', 'order_items', 'products'], null, null, 35, 'Esse relatorio mostra se pedidos com desconto ainda preservam margem.', array['select', 'draft'], 48, false),
  ('00000000-0000-0000-0000-000000000459', '00000000-0000-0000-0000-000000000212', 'Receita por cidade', 'negocio-receita-por-cidade', 'free_select', 'hard', 'Pergunta de negocio: quais cidades geraram mais receita valida em fevereiro de 2026? Retorne `city`, `state`, `order_count` e `sales_total`, considerando pedidos `paid`, `shipped` ou `delivered`, ordenando por `sales_total` decrescente.', null, 'SELECT c.city, c.state, count(o.id) AS order_count, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.city, c.state ORDER BY sales_total DESC', array[]::text[], array['customers', 'orders'], null, null, 35, 'A receita por cidade combina localizacao do cliente com pedidos validos.', array['select', 'draft'], 49, false),
  ('00000000-0000-0000-0000-000000000460', '00000000-0000-0000-0000-000000000212', 'Top clientes por margem valida', 'negocio-top-clientes-margem-valida', 'free_select', 'hard', 'Pergunta de negocio: quais sao os 5 clientes com maior margem bruta em pedidos validos de fevereiro de 2026? Retorne `full_name`, `sales_total` e `gross_profit`, ordenando por `gross_profit` decrescente e limitando em 5.', null, 'SELECT c.full_name, sum(oi.line_total) AS sales_total, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.full_name ORDER BY gross_profit DESC LIMIT 5', array[]::text[], array['customers', 'orders', 'order_items', 'products'], null, null, 35, 'O ranking por margem prioriza clientes que mais contribuem para resultado.', array['select', 'draft'], 50, false),
  ('00000000-0000-0000-0000-000000000461', '00000000-0000-0000-0000-000000000206', 'Produtos com suas categorias ativas', 'joins-basicos-produtos-categorias-ativas', 'free_select', 'medium', 'Liste produtos ativos com sua categoria. Retorne `product_name`, `category_name` e `price`, usando JOIN entre `products` e `categories`, ordenando por `category_name` e `product_name`.', null, 'SELECT p.name AS product_name, c.name AS category_name, p.price FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id WHERE p.active = true ORDER BY category_name, product_name', array[]::text[], array['products', 'categories'], null, null, 20, 'JOIN basico conecta produtos a categorias pela chave estrangeira.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000462', '00000000-0000-0000-0000-000000000206', 'Pedidos com cliente e estado', 'joins-basicos-pedidos-cliente-estado', 'free_select', 'medium', 'Liste pedidos com cliente e estado. Retorne `order_number`, `full_name`, `state` e `total_amount`, usando JOIN entre `orders` e `customers`, ordenando por `order_number`.', null, 'SELECT o.order_number, c.full_name, c.state, o.total_amount FROM challenge_data.orders o JOIN challenge_data.customers c ON c.id = o.customer_id ORDER BY o.order_number', array[]::text[], array['orders', 'customers'], null, null, 20, 'O pedido guarda o identificador do cliente.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000463', '00000000-0000-0000-0000-000000000206', 'Pagamentos pagos com numero do pedido', 'joins-basicos-pagamentos-pagos-pedido', 'free_select', 'medium', 'Liste pagamentos pagos com o numero do pedido. Retorne `order_number`, `payment_method` e `amount`, filtrando `payments.status = ''paid''`, ordenando por `amount` decrescente.', null, 'SELECT o.order_number, p.payment_method, p.amount FROM challenge_data.payments p JOIN challenge_data.orders o ON o.id = p.order_id WHERE p.status = ''paid'' ORDER BY p.amount DESC', array[]::text[], array['payments', 'orders'], null, null, 20, 'Pagamentos se ligam a pedidos por `order_id`.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000464', '00000000-0000-0000-0000-000000000206', 'Entregas entregues com pedido', 'joins-basicos-entregas-entregues-pedido', 'free_select', 'medium', 'Liste entregas concluidas com numero do pedido. Retorne `order_number`, `carrier` e `delivered_at`, filtrando `shipments.status = ''delivered''`, ordenando por `delivered_at`.', null, 'SELECT o.order_number, s.carrier, s.delivered_at FROM challenge_data.shipments s JOIN challenge_data.orders o ON o.id = s.order_id WHERE s.status = ''delivered'' ORDER BY s.delivered_at', array[]::text[], array['shipments', 'orders'], null, null, 20, 'A entrega possui `order_id` para encontrar o pedido.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000465', '00000000-0000-0000-0000-000000000206', 'Itens com produto e categoria', 'joins-basicos-itens-produto-categoria', 'free_select', 'hard', 'Liste itens de pedido com produto e categoria. Retorne `order_id`, `product_name`, `category_name`, `quantity` e `line_total`, usando JOINs entre `order_items`, `products` e `categories`, ordenando por `line_total` decrescente e limitando em 12.', null, 'SELECT oi.order_id, p.name AS product_name, c.name AS category_name, oi.quantity, oi.line_total FROM challenge_data.order_items oi JOIN challenge_data.products p ON p.id = oi.product_id JOIN challenge_data.categories c ON c.id = p.category_id ORDER BY oi.line_total DESC LIMIT 12', array[]::text[], array['order_items', 'products', 'categories'], null, null, 35, 'Dois JOINs enriquecem itens com produto e categoria.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000466', '00000000-0000-0000-0000-000000000206', 'Pedidos pagos com cliente e pagamento', 'joins-basicos-pedidos-pagos-cliente-pagamento', 'free_select', 'hard', 'Liste pedidos com cliente e pagamento aprovado. Retorne `full_name`, `order_number`, `payment_method` e `amount`, filtrando pagamentos `paid`, ordenando por `full_name` e `order_number`.', null, 'SELECT c.full_name, o.order_number, p.payment_method, p.amount FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.payments p ON p.order_id = o.id WHERE p.status = ''paid'' ORDER BY c.full_name, o.order_number', array[]::text[], array['customers', 'orders', 'payments'], null, null, 35, 'JOIN em cadeia conecta cliente, pedido e pagamento.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000467', '00000000-0000-0000-0000-000000000206', 'Produtos de categorias com estoque', 'joins-basicos-produtos-categorias-estoque', 'free_select', 'hard', 'Liste produtos de categorias com estoque atual. Retorne `category_name`, `product_name`, `stock_quantity` e `price`, filtrando produtos com `stock_quantity > 0`, ordenando por `category_name` e `stock_quantity` decrescente.', null, 'SELECT c.name AS category_name, p.name AS product_name, p.stock_quantity, p.price FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id WHERE p.stock_quantity > 0 ORDER BY category_name, p.stock_quantity DESC', array[]::text[], array['categories', 'products'], null, null, 35, 'O filtro de estoque fica em produtos, mas o nome da categoria vem do JOIN.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000468', '00000000-0000-0000-0000-000000000206', 'Pedidos por cliente de Rondonia', 'joins-basicos-pedidos-cliente-rondonia', 'free_select', 'hard', 'Liste pedidos de clientes de Rondonia. Retorne `full_name`, `order_number`, `status` e `total_amount`, usando JOIN entre `customers` e `orders`, filtrando `state = ''Rondonia''`, ordenando por `total_amount` decrescente.', null, 'SELECT c.full_name, o.order_number, o.status, o.total_amount FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE c.state = ''Rondonia'' ORDER BY o.total_amount DESC', array[]::text[], array['customers', 'orders'], null, null, 35, 'Filtros podem usar a tabela de dimensao enquanto valores vem da tabela de fatos.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000469', '00000000-0000-0000-0000-000000000206', 'Pagamentos com cliente', 'joins-basicos-pagamentos-com-cliente', 'free_select', 'hard', 'Liste pagamentos com nome do cliente. Retorne `full_name`, `payment_method`, `status` e `amount`, usando JOINs entre `payments`, `orders` e `customers`, ordenando por `amount` decrescente e limitando em 10.', null, 'SELECT c.full_name, p.payment_method, p.status, p.amount FROM challenge_data.payments p JOIN challenge_data.orders o ON o.id = p.order_id JOIN challenge_data.customers c ON c.id = o.customer_id ORDER BY p.amount DESC LIMIT 10', array[]::text[], array['payments', 'orders', 'customers'], null, null, 35, 'Pagamento chega ao cliente passando pelo pedido.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000470', '00000000-0000-0000-0000-000000000206', 'Entregas com cliente e status do pedido', 'joins-basicos-entregas-cliente-status-pedido', 'free_select', 'hard', 'Liste entregas com cliente e status do pedido. Retorne `full_name`, `order_number`, `order_status`, `shipment_status` e `carrier`, usando JOINs entre `shipments`, `orders` e `customers`, ordenando por `order_number`.', null, 'SELECT c.full_name, o.order_number, o.status AS order_status, s.status AS shipment_status, s.carrier FROM challenge_data.shipments s JOIN challenge_data.orders o ON o.id = s.order_id JOIN challenge_data.customers c ON c.id = o.customer_id ORDER BY o.order_number', array[]::text[], array['shipments', 'orders', 'customers'], null, null, 35, 'Aliases evitam ambiguidade quando duas tabelas tem coluna `status`.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000471', '00000000-0000-0000-0000-000000000207', 'Clientes sem pedidos pagos', 'joins-intermediarios-clientes-sem-pedidos-pagos', 'free_select', 'medium', 'Use LEFT JOIN para listar clientes que nao tem pedidos `paid`. Retorne `full_name` e `state`, ordenando por `full_name`.', null, 'SELECT c.full_name, c.state FROM challenge_data.customers c LEFT JOIN challenge_data.orders o ON o.customer_id = c.id AND o.status = ''paid'' WHERE o.id IS NULL ORDER BY c.full_name', array[]::text[], array['customers', 'orders'], null, null, 20, 'LEFT JOIN com filtro no JOIN encontra ausencias especificas.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000472', '00000000-0000-0000-0000-000000000207', 'Produtos sem venda valida', 'joins-intermediarios-produtos-sem-venda-valida', 'free_select', 'medium', 'Use LEFT JOIN para listar produtos que nao aparecem em pedidos `paid`, `shipped` ou `delivered`. Retorne `product_name` e `sku`, ordenando por `product_name`.', null, 'SELECT p.name AS product_name, p.sku FROM challenge_data.products p LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id LEFT JOIN challenge_data.orders o ON o.id = oi.order_id AND o.status IN (''paid'', ''shipped'', ''delivered'') WHERE o.id IS NULL ORDER BY product_name', array[]::text[], array['products', 'order_items', 'orders'], null, null, 20, 'A ausencia de pedido valido aparece quando o pedido unido fica nulo.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000473', '00000000-0000-0000-0000-000000000207', 'Total de pedidos por cliente', 'joins-intermediarios-total-pedidos-cliente', 'free_select', 'medium', 'Liste todos os clientes com quantidade de pedidos. Retorne `full_name` e `order_count`, usando LEFT JOIN, ordenando por `order_count` decrescente e `full_name`.', null, 'SELECT c.full_name, count(o.id) AS order_count FROM challenge_data.customers c LEFT JOIN challenge_data.orders o ON o.customer_id = c.id GROUP BY c.id, c.full_name ORDER BY order_count DESC, c.full_name', array[]::text[], array['customers', 'orders'], null, null, 20, 'COUNT da coluna da tabela ligada evita contar linha nula do LEFT JOIN.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000474', '00000000-0000-0000-0000-000000000207', 'Vendas por categoria com zero', 'joins-intermediarios-vendas-categoria-zero', 'free_select', 'medium', 'Liste todas as categorias com venda total em pedidos validos, incluindo categorias sem venda. Retorne `category_name` e `sales_total`, usando LEFT JOIN e `coalesce`, ordenando por `sales_total` decrescente.', null, 'SELECT c.name AS category_name, coalesce(sum(CASE WHEN o.status IN (''paid'', ''shipped'', ''delivered'') THEN oi.line_total ELSE 0 END), 0) AS sales_total FROM challenge_data.categories c LEFT JOIN challenge_data.products p ON p.category_id = c.id LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id LEFT JOIN challenge_data.orders o ON o.id = oi.order_id GROUP BY c.name ORDER BY sales_total DESC', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 20, 'CASE dentro da soma preserva categorias sem pedidos validos.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000475', '00000000-0000-0000-0000-000000000207', 'Margem por categoria em pedidos validos', 'joins-intermediarios-margem-categoria-validos', 'free_select', 'hard', 'Calcule margem bruta por categoria em pedidos validos. Retorne `category_name`, `sales_total` e `gross_profit`, ordenando por `gross_profit` decrescente.', null, 'SELECT c.name AS category_name, sum(oi.line_total) AS sales_total, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.name ORDER BY gross_profit DESC', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'Agregacoes depois de multiplos JOINs criam metricas por dimensao.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000476', '00000000-0000-0000-0000-000000000207', 'Pedidos com pagamento sem entrega', 'joins-intermediarios-pagamento-sem-entrega', 'free_select', 'hard', 'Liste pedidos com pagamento `paid` que nao possuem entrega. Retorne `order_number`, `payment_method` e `amount`, usando JOIN em `payments` e LEFT JOIN em `shipments`, ordenando por `amount` decrescente.', null, 'SELECT o.order_number, p.payment_method, p.amount FROM challenge_data.orders o JOIN challenge_data.payments p ON p.order_id = o.id LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE p.status = ''paid'' AND s.id IS NULL ORDER BY p.amount DESC', array[]::text[], array['orders', 'payments', 'shipments'], null, null, 35, 'Combinar JOIN e LEFT JOIN permite achar lacunas apos pagamento.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000477', '00000000-0000-0000-0000-000000000207', 'Receita por estado e status', 'joins-intermediarios-receita-estado-status', 'free_select', 'hard', 'Some receita por estado e status do pedido. Retorne `state`, `status` e `sales_total`, considerando pedidos de fevereiro de 2026, ordenando por `state` e `sales_total` decrescente.', null, 'SELECT c.state, o.status, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' GROUP BY c.state, o.status ORDER BY c.state, sales_total DESC', array[]::text[], array['customers', 'orders'], null, null, 35, 'Agrupar por duas dimensoes revela composicao do resultado.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000478', '00000000-0000-0000-0000-000000000207', 'Produtos vendidos por cliente', 'joins-intermediarios-produtos-vendidos-cliente', 'free_select', 'hard', 'Liste cliente e produto com unidades compradas em pedidos validos. Retorne `full_name`, `product_name` e `units_sold`, ordenando por `full_name` e `units_sold` decrescente.', null, 'SELECT c.full_name, p.name AS product_name, sum(oi.quantity) AS units_sold FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.full_name, p.name ORDER BY c.full_name, units_sold DESC', array[]::text[], array['customers', 'orders', 'order_items', 'products'], null, null, 35, 'Esse relatorio percorre cliente, pedido, item e produto.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000479', '00000000-0000-0000-0000-000000000207', 'Transportadora por status do pedido', 'joins-intermediarios-transportadora-status-pedido', 'free_select', 'hard', 'Conte pedidos por transportadora e status do pedido. Retorne `carrier`, `order_status` e `order_count`, usando JOIN entre `shipments` e `orders`, ordenando por `carrier` e `order_count` decrescente.', null, 'SELECT s.carrier, o.status AS order_status, count(*) AS order_count FROM challenge_data.shipments s JOIN challenge_data.orders o ON o.id = s.order_id GROUP BY s.carrier, o.status ORDER BY s.carrier, order_count DESC', array[]::text[], array['shipments', 'orders'], null, null, 35, 'Agrupar status por transportadora mostra composicao logistica.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000480', '00000000-0000-0000-0000-000000000207', 'Financeiro por cliente', 'joins-intermediarios-financeiro-por-cliente', 'free_select', 'hard', 'Calcule financeiro liquido por cliente em fevereiro de 2026. Retorne `full_name` e `net_amount`, somando `revenue` positivo e demais tipos negativos, ordenando por `net_amount` decrescente.', null, 'SELECT c.full_name, sum(CASE WHEN ft.type = ''revenue'' THEN ft.amount ELSE -ft.amount END) AS net_amount FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id WHERE ft.transaction_date >= DATE ''2026-02-01'' AND ft.transaction_date < DATE ''2026-03-01'' GROUP BY c.id, c.full_name ORDER BY net_amount DESC', array[]::text[], array['customers', 'orders', 'financial_transactions'], null, null, 35, 'Financeiro por cliente exige atravessar pedidos ate transacoes.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000481', '00000000-0000-0000-0000-000000000208', 'CTE pedidos validos', 'ctes-pedidos-validos-total', 'free_select', 'medium', 'Crie a CTE `valid_orders` com pedidos `paid`, `shipped` ou `delivered` de fevereiro de 2026. Retorne `order_count` e `sales_total` a partir dela.', null, 'WITH valid_orders AS (SELECT id, total_amount FROM challenge_data.orders WHERE order_date >= TIMESTAMP ''2026-02-01'' AND order_date < TIMESTAMP ''2026-03-01'' AND status IN (''paid'', ''shipped'', ''delivered'')) SELECT count(id) AS order_count, sum(total_amount) AS sales_total FROM valid_orders', array[]::text[], array['orders'], null, null, 20, 'A CTE isola o filtro de pedidos validos antes da agregacao.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000482', '00000000-0000-0000-0000-000000000208', 'CTE produtos ativos caros', 'ctes-produtos-ativos-caros', 'free_select', 'medium', 'Crie a CTE `active_products` com produtos ativos. Retorne `name` e `price` dos produtos com `price >= 500`, ordenando por `price` decrescente.', null, 'WITH active_products AS (SELECT name, price FROM challenge_data.products WHERE active = true) SELECT name, price FROM active_products WHERE price >= 500 ORDER BY price DESC', array[]::text[], array['products'], null, null, 20, 'A CTE separa o filtro de ativo do filtro de preco.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000483', '00000000-0000-0000-0000-000000000208', 'CTE receita por dia', 'ctes-receita-por-dia', 'free_select', 'medium', 'Crie a CTE `daily_sales` com vendas por dia em pedidos validos de fevereiro de 2026. Retorne `order_day` e `sales_total`, ordenando por `order_day`.', null, 'WITH daily_sales AS (SELECT order_date::date AS order_day, sum(total_amount) AS sales_total FROM challenge_data.orders WHERE order_date >= TIMESTAMP ''2026-02-01'' AND order_date < TIMESTAMP ''2026-03-01'' AND status IN (''paid'', ''shipped'', ''delivered'') GROUP BY order_day) SELECT order_day, sales_total FROM daily_sales ORDER BY order_day', array[]::text[], array['orders'], null, null, 20, 'CTE agregada pode ser consultada como uma tabela temporaria da query.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000484', '00000000-0000-0000-0000-000000000208', 'CTE estoque baixo', 'ctes-estoque-baixo', 'free_select', 'medium', 'Crie a CTE `low_stock` com produtos ativos e estoque menor que 5. Retorne `name`, `sku` e `stock_quantity`, ordenando por `stock_quantity` e `name`.', null, 'WITH low_stock AS (SELECT name, sku, stock_quantity FROM challenge_data.products WHERE active = true AND stock_quantity < 5) SELECT name, sku, stock_quantity FROM low_stock ORDER BY stock_quantity, name', array[]::text[], array['products'], null, null, 20, 'A CTE nomeia o conjunto de produtos com risco de estoque.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000485', '00000000-0000-0000-0000-000000000208', 'CTE ranking clientes', 'ctes-ranking-clientes', 'free_select', 'hard', 'Use CTE `customer_sales` para somar pedidos validos por cliente em fevereiro de 2026. Retorne `full_name`, `total_spent` e `customer_rank` com `rank()` por `total_spent` decrescente, ordenando por `customer_rank`.', null, 'WITH customer_sales AS (SELECT c.full_name, sum(o.total_amount) AS total_spent FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.full_name) SELECT full_name, total_spent, rank() OVER (ORDER BY total_spent DESC) AS customer_rank FROM customer_sales ORDER BY customer_rank, full_name', array[]::text[], array['customers', 'orders'], null, null, 35, 'A CTE calcula o total antes da funcao de janela.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000486', '00000000-0000-0000-0000-000000000208', 'CTEs vendas e estoque categoria', 'ctes-vendas-estoque-categoria', 'free_select', 'hard', 'Crie CTEs `category_sales` e `category_stock`. Retorne `category_name`, `sales_total` e `total_stock`, juntando as CTEs e ordenando por `sales_total` decrescente.', null, 'WITH category_sales AS (SELECT c.id, c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.id, c.name), category_stock AS (SELECT c.id, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.id) SELECT cs.category_name, cs.sales_total, st.total_stock FROM category_sales cs JOIN category_stock st ON st.id = cs.id ORDER BY cs.sales_total DESC', array[]::text[], array['categories', 'products', 'order_items', 'orders'], null, null, 35, 'Duas CTEs evitam misturar granularidades de venda e estoque.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000487', '00000000-0000-0000-0000-000000000208', 'CTE margem produtos', 'ctes-margem-produtos', 'free_select', 'hard', 'Crie a CTE `product_margin` com `product_name`, `category_name` e `margin`. Retorne produtos com margem maior que 200, ordenando por `margin` decrescente.', null, 'WITH product_margin AS (SELECT p.name AS product_name, c.name AS category_name, p.price - p.cost AS margin FROM challenge_data.products p JOIN challenge_data.categories c ON c.id = p.category_id WHERE p.active = true) SELECT product_name, category_name, margin FROM product_margin WHERE margin > 200 ORDER BY margin DESC', array[]::text[], array['products', 'categories'], null, null, 35, 'A CTE facilita filtrar uma expressao calculada com alias.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000488', '00000000-0000-0000-0000-000000000208', 'CTE pagamentos por metodo', 'ctes-pagamentos-por-metodo', 'free_select', 'hard', 'Crie a CTE `method_totals` com total pago por metodo em fevereiro de 2026. Retorne `payment_method`, `payment_count` e `paid_total` apenas para metodos com `paid_total >= 1000`, ordenando por `paid_total` decrescente.', null, 'WITH method_totals AS (SELECT payment_method, count(*) AS payment_count, sum(amount) AS paid_total FROM challenge_data.payments WHERE paid_at >= TIMESTAMP ''2026-02-01'' AND paid_at < TIMESTAMP ''2026-03-01'' AND status = ''paid'' GROUP BY payment_method) SELECT payment_method, payment_count, paid_total FROM method_totals WHERE paid_total >= 1000 ORDER BY paid_total DESC', array[]::text[], array['payments'], null, null, 35, 'A CTE permite filtrar uma agregacao pelo alias.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000489', '00000000-0000-0000-0000-000000000208', 'CTE pedidos com lucro', 'ctes-pedidos-com-lucro', 'free_select', 'hard', 'Crie a CTE `order_profit` com lucro bruto por pedido valido. Retorne `order_number` e `gross_profit` para pedidos com `gross_profit > 500`, ordenando por `gross_profit` decrescente.', null, 'WITH order_profit AS (SELECT o.order_number, sum((p.price - p.cost) * oi.quantity) AS gross_profit FROM challenge_data.orders o JOIN challenge_data.order_items oi ON oi.order_id = o.id JOIN challenge_data.products p ON p.id = oi.product_id WHERE o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY o.order_number) SELECT order_number, gross_profit FROM order_profit WHERE gross_profit > 500 ORDER BY gross_profit DESC', array[]::text[], array['orders', 'order_items', 'products'], null, null, 35, 'A CTE transforma margem por pedido em uma tabela filtravel.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000490', '00000000-0000-0000-0000-000000000208', 'CTE clientes por estado', 'ctes-clientes-por-estado-receita', 'free_select', 'hard', 'Use CTE `state_sales` para somar receita valida por estado em fevereiro de 2026. Retorne `state`, `customer_count` e `sales_total`, ordenando por `sales_total` decrescente.', null, 'WITH state_sales AS (SELECT c.state, count(DISTINCT c.id) AS customer_count, sum(o.total_amount) AS sales_total FROM challenge_data.customers c JOIN challenge_data.orders o ON o.customer_id = c.id WHERE o.order_date >= TIMESTAMP ''2026-02-01'' AND o.order_date < TIMESTAMP ''2026-03-01'' AND o.status IN (''paid'', ''shipped'', ''delivered'') GROUP BY c.state) SELECT state, customer_count, sales_total FROM state_sales ORDER BY sales_total DESC', array[]::text[], array['customers', 'orders'], null, null, 35, 'COUNT DISTINCT evita duplicar clientes com varios pedidos.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000491', '00000000-0000-0000-0000-000000000209', 'UNION clientes SP RJ', 'union-clientes-sp-rj', 'free_select', 'medium', 'Use UNION para combinar clientes de SP e RJ. Retorne `full_name`, `state` e `region_group`, usando `region_group = ''sudeste''`, ordenando por `state` e `full_name`.', null, 'SELECT full_name, state, ''sudeste'' AS region_group FROM challenge_data.customers WHERE state = ''SP'' UNION SELECT full_name, state, ''sudeste'' AS region_group FROM challenge_data.customers WHERE state = ''RJ'' ORDER BY state, full_name', array[]::text[], array['customers'], null, null, 20, 'UNION combina consultas com as mesmas colunas.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000492', '00000000-0000-0000-0000-000000000209', 'UNION ALL produtos ativos e inativos', 'union-produtos-ativos-inativos', 'free_select', 'medium', 'Use UNION ALL para listar produtos ativos e inativos com um rotulo. Retorne `product_name` e `product_status`, ordenando por `product_status` e `product_name`.', null, 'SELECT name AS product_name, ''ativo'' AS product_status FROM challenge_data.products WHERE active = true UNION ALL SELECT name AS product_name, ''inativo'' AS product_status FROM challenge_data.products WHERE active = false ORDER BY product_status, product_name', array[]::text[], array['products'], null, null, 20, 'UNION ALL preserva todos os resultados das duas consultas.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000493', '00000000-0000-0000-0000-000000000209', 'UNION pedidos pagos e entregues', 'union-pedidos-pagos-entregues', 'free_select', 'medium', 'Use UNION para combinar pedidos `paid` e `delivered`. Retorne `order_number`, `status` e `total_amount`, ordenando por `status` e `order_number`.', null, 'SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''paid'' UNION SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''delivered'' ORDER BY status, order_number', array[]::text[], array['orders'], null, null, 20, 'UNION remove duplicatas e exige colunas compativeis.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000494', '00000000-0000-0000-0000-000000000209', 'UNION eventos de pedido e pagamento', 'union-eventos-pedido-pagamento', 'free_select', 'medium', 'Use UNION ALL para montar uma linha do tempo com pedidos e pagamentos antes de 2026-02-05. Retorne `reference`, `event_type` e `event_at`, ordenando por `event_at` e `event_type`.', null, 'SELECT order_number AS reference, ''order'' AS event_type, order_date AS event_at FROM challenge_data.orders WHERE order_date < TIMESTAMP ''2026-02-05'' UNION ALL SELECT payment_method AS reference, ''payment'' AS event_type, paid_at AS event_at FROM challenge_data.payments WHERE paid_at < TIMESTAMP ''2026-02-05'' AND paid_at IS NOT NULL ORDER BY event_at, event_type', array[]::text[], array['orders', 'payments'], null, null, 20, 'UNION ALL permite mesclar eventos de tabelas diferentes em um formato comum.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000495', '00000000-0000-0000-0000-000000000209', 'UNION categorias e produtos caros', 'union-categorias-produtos-caros', 'free_select', 'hard', 'Use UNION ALL para combinar categorias e produtos com preco maior ou igual a 1000. Retorne `name` e `source`, onde categorias usam `source = ''category''` e produtos usam `source = ''product''`, ordenando por `source` e `name`.', null, 'SELECT name, ''category'' AS source FROM challenge_data.categories UNION ALL SELECT name, ''product'' AS source FROM challenge_data.products WHERE price >= 1000 ORDER BY source, name', array[]::text[], array['categories', 'products'], null, null, 35, 'As duas consultas precisam produzir colunas com tipos compativeis.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000496', '00000000-0000-0000-0000-000000000209', 'UNION receitas e estornos', 'union-receitas-estornos', 'free_select', 'hard', 'Use UNION ALL para combinar transacoes `revenue` e `refund` de fevereiro de 2026. Retorne `order_id`, `type` e `amount`, ordenando por `type` e `amount` decrescente.', null, 'SELECT order_id, type, amount FROM challenge_data.financial_transactions WHERE transaction_date >= DATE ''2026-02-01'' AND transaction_date < DATE ''2026-03-01'' AND type = ''revenue'' UNION ALL SELECT order_id, type, amount FROM challenge_data.financial_transactions WHERE transaction_date >= DATE ''2026-02-01'' AND transaction_date < DATE ''2026-03-01'' AND type = ''refund'' ORDER BY type, amount DESC', array[]::text[], array['financial_transactions'], null, null, 35, 'UNION ALL mantem todas as transacoes financeiras selecionadas.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000497', '00000000-0000-0000-0000-000000000209', 'UNION buscas por nome', 'union-buscas-por-nome', 'free_select', 'hard', 'Use UNION ALL para combinar clientes com nome contendo `Silva` e produtos com nome contendo `SQL`. Retorne `result_name` e `result_type`, ordenando por `result_type` e `result_name`.', null, 'SELECT full_name AS result_name, ''customer'' AS result_type FROM challenge_data.customers WHERE full_name LIKE ''%Silva%'' UNION ALL SELECT name AS result_name, ''product'' AS result_type FROM challenge_data.products WHERE name LIKE ''%SQL%'' ORDER BY result_type, result_name', array[]::text[], array['customers', 'products'], null, null, 35, 'UNION pode servir como busca simples em entidades diferentes.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000498', '00000000-0000-0000-0000-000000000209', 'UNION regioes de clientes', 'union-regioes-clientes', 'free_select', 'hard', 'Use UNION ALL para classificar clientes de Rondonia e AM como `norte`, e clientes de SP, RJ e MG como `sudeste`. Retorne `full_name`, `state` e `region`, ordenando por `region` e `full_name`.', null, 'SELECT full_name, state, ''norte'' AS region FROM challenge_data.customers WHERE state IN (''Rondonia'', ''AM'') UNION ALL SELECT full_name, state, ''sudeste'' AS region FROM challenge_data.customers WHERE state IN (''SP'', ''RJ'', ''MG'') ORDER BY region, full_name', array[]::text[], array['customers'], null, null, 35, 'Duas consultas com filtros diferentes podem virar um resultado classificado.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000499', '00000000-0000-0000-0000-000000000209', 'UNION contagens operacionais', 'union-contagens-operacionais', 'free_select', 'hard', 'Use UNION ALL para combinar contagem por metodo de pagamento e contagem por status de pedido. Retorne `label`, `source` e `total`, ordenando por `source` e `label`.', null, 'SELECT payment_method AS label, ''payment_method'' AS source, count(*) AS total FROM challenge_data.payments GROUP BY payment_method UNION ALL SELECT status AS label, ''order_status'' AS source, count(*) AS total FROM challenge_data.orders GROUP BY status ORDER BY source, label', array[]::text[], array['payments', 'orders'], null, null, 35, 'Agregacoes separadas podem ser empilhadas se os formatos coincidirem.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000500', '00000000-0000-0000-0000-000000000209', 'UNION CTE pedidos selecionados', 'union-cte-pedidos-selecionados', 'free_select', 'hard', 'Crie a CTE `selected_orders` usando UNION ALL para combinar pedidos com `total_amount >= 2000` e pedidos `pending`. Retorne `order_number`, `status` e `total_amount`, ordenando por `total_amount` decrescente.', null, 'WITH selected_orders AS (SELECT order_number, status, total_amount FROM challenge_data.orders WHERE total_amount >= 2000 UNION ALL SELECT order_number, status, total_amount FROM challenge_data.orders WHERE status = ''pending'') SELECT order_number, status, total_amount FROM selected_orders ORDER BY total_amount DESC', array[]::text[], array['orders'], null, null, 35, 'UNION dentro de CTE permite tratar a combinacao antes da ordenacao final.', array['select', 'draft'], 20, false),
  ('00000000-0000-0000-0000-000000000501', '00000000-0000-0000-0000-000000000210', 'Revisao clientes com gasto valido', 'revisao-clientes-gasto-valido', 'free_select', 'medium', 'Com uma CTE `valid_orders`, retorne os 5 clientes com maior gasto em pedidos validos. Retorne `full_name` e `total_spent`, ordenando por `total_spent` decrescente e limitando em 5.', null, 'WITH valid_orders AS (SELECT customer_id, total_amount FROM challenge_data.orders WHERE status IN (''paid'', ''shipped'', ''delivered'')) SELECT c.full_name, sum(v.total_amount) AS total_spent FROM valid_orders v JOIN challenge_data.customers c ON c.id = v.customer_id GROUP BY c.full_name ORDER BY total_spent DESC LIMIT 5', array[]::text[], array['orders', 'customers'], null, null, 20, 'A CTE separa o filtro de pedidos antes do ranking por cliente.', array['select', 'draft'], 11, false),
  ('00000000-0000-0000-0000-000000000502', '00000000-0000-0000-0000-000000000210', 'Revisao produtos acima da media', 'revisao-produtos-acima-media', 'free_select', 'medium', 'Use CTE `category_avg` para calcular preco medio por categoria. Retorne `product_name`, `price` e `average_price` dos produtos com preco acima da media da categoria, ordenando por `price` decrescente.', null, 'WITH category_avg AS (SELECT category_id, round(avg(price), 2) AS average_price FROM challenge_data.products GROUP BY category_id) SELECT p.name AS product_name, p.price, ca.average_price FROM challenge_data.products p JOIN category_avg ca ON ca.category_id = p.category_id WHERE p.price > ca.average_price ORDER BY p.price DESC', array[]::text[], array['products'], null, null, 20, 'A media por categoria vira referencia para comparar cada produto.', array['select', 'draft'], 12, false),
  ('00000000-0000-0000-0000-000000000503', '00000000-0000-0000-0000-000000000210', 'Revisao clientes sem entregas', 'revisao-clientes-sem-entregas', 'free_select', 'medium', 'Liste clientes que nao tem pedidos entregues (`orders.status = ''delivered''`). Retorne `full_name` e `state`, usando LEFT JOIN, ordenando por `full_name`.', null, 'SELECT c.full_name, c.state FROM challenge_data.customers c LEFT JOIN challenge_data.orders o ON o.customer_id = c.id AND o.status = ''delivered'' WHERE o.id IS NULL ORDER BY c.full_name', array[]::text[], array['customers', 'orders'], null, null, 20, 'LEFT JOIN com filtro no ON encontra clientes sem relacionamento do tipo desejado.', array['select', 'draft'], 13, false),
  ('00000000-0000-0000-0000-000000000504', '00000000-0000-0000-0000-000000000210', 'Revisao pedidos pagos sem envio', 'revisao-pedidos-pagos-sem-envio', 'free_select', 'medium', 'Liste pedidos `paid` que nao possuem registro em `shipments`. Retorne `order_number`, `total_amount` e `status`, usando LEFT JOIN, ordenando por `total_amount` decrescente.', null, 'SELECT o.order_number, o.total_amount, o.status FROM challenge_data.orders o LEFT JOIN challenge_data.shipments s ON s.order_id = o.id WHERE o.status = ''paid'' AND s.id IS NULL ORDER BY o.total_amount DESC', array[]::text[], array['orders', 'shipments'], null, null, 20, 'Esse padrao combina filtro de status e ausencia de entrega.', array['select', 'draft'], 14, false),
  ('00000000-0000-0000-0000-000000000505', '00000000-0000-0000-0000-000000000210', 'Revisao categoria estoque vendas', 'revisao-categoria-estoque-vendas', 'free_select', 'hard', 'Com CTEs `category_stock` e `category_sales`, retorne `category_name`, `total_stock` e `sales_total` para todas as categorias. Ordene por `sales_total` decrescente.', null, 'WITH category_stock AS (SELECT c.id, c.name AS category_name, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.id, c.name), category_sales AS (SELECT c.id, coalesce(sum(oi.line_total), 0) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id LEFT JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.id) SELECT cs.category_name, cs.total_stock, s.sales_total FROM category_stock cs JOIN category_sales s ON s.id = cs.id ORDER BY s.sales_total DESC', array[]::text[], array['categories', 'products', 'order_items'], null, null, 35, 'Separar CTEs impede que estoque seja multiplicado por itens vendidos.', array['select', 'draft'], 15, false),
  ('00000000-0000-0000-0000-000000000506', '00000000-0000-0000-0000-000000000210', 'Revisao descontos e frete gratis', 'revisao-descontos-frete-gratis', 'free_select', 'hard', 'Use UNION para listar pedidos com desconto e pedidos com frete gratis. Retorne `order_number`, `reason` e `amount`, ordenando por `reason` e `order_number`.', null, 'SELECT order_number, ''discount'' AS reason, discount_amount AS amount FROM challenge_data.orders WHERE discount_amount > 0 UNION SELECT order_number, ''free_shipping'' AS reason, shipping_amount AS amount FROM challenge_data.orders WHERE shipping_amount = 0 ORDER BY reason, order_number', array[]::text[], array['orders'], null, null, 35, 'UNION combina dois criterios comerciais em uma lista unica.', array['select', 'draft'], 16, false),
  ('00000000-0000-0000-0000-000000000507', '00000000-0000-0000-0000-000000000210', 'Revisao linha do tempo recente', 'revisao-linha-tempo-recente', 'free_select', 'hard', 'Com CTE `events`, combine pedidos e pagamentos usando UNION ALL. Retorne `reference`, `event_type` e `event_at` para eventos a partir de 2026-02-18, ordenando por `event_at` e `event_type`.', null, 'WITH events AS (SELECT order_number AS reference, ''order'' AS event_type, order_date AS event_at FROM challenge_data.orders UNION ALL SELECT payment_method AS reference, ''payment'' AS event_type, paid_at AS event_at FROM challenge_data.payments WHERE paid_at IS NOT NULL) SELECT reference, event_type, event_at FROM events WHERE event_at >= TIMESTAMP ''2026-02-18'' ORDER BY event_at, event_type', array[]::text[], array['orders', 'payments'], null, null, 35, 'A CTE cria uma linha do tempo combinada antes do filtro final.', array['select', 'draft'], 17, false),
  ('00000000-0000-0000-0000-000000000508', '00000000-0000-0000-0000-000000000210', 'Revisao unidades validas por produto', 'revisao-unidades-validas-produto', 'free_select', 'hard', 'Some unidades vendidas por produto em pedidos que nao estejam `cancelled`. Retorne `product_name` e `units_sold`, ordenando por `units_sold` decrescente e `product_name`.', null, 'SELECT p.name AS product_name, sum(oi.quantity) AS units_sold FROM challenge_data.products p JOIN challenge_data.order_items oi ON oi.product_id = p.id JOIN challenge_data.orders o ON o.id = oi.order_id WHERE o.status <> ''cancelled'' GROUP BY p.name ORDER BY units_sold DESC, product_name', array[]::text[], array['products', 'order_items', 'orders'], null, null, 35, 'A revisao combina JOIN, filtro, agregacao e ordenacao.', array['select', 'draft'], 18, false),
  ('00000000-0000-0000-0000-000000000509', '00000000-0000-0000-0000-000000000210', 'Revisao financeiro liquido pedido', 'revisao-financeiro-liquido-pedido', 'free_select', 'hard', 'Calcule o valor liquido por pedido usando transacoes financeiras. Retorne `order_number` e `net_amount`, tratando `refund`, `fee` e `shipping_cost` como negativos, ordenando por `net_amount` decrescente.', null, 'SELECT o.order_number, sum(CASE WHEN ft.type IN (''refund'', ''fee'', ''shipping_cost'') THEN -ft.amount ELSE ft.amount END) AS net_amount FROM challenge_data.orders o JOIN challenge_data.financial_transactions ft ON ft.order_id = o.id GROUP BY o.order_number ORDER BY net_amount DESC', array[]::text[], array['orders', 'financial_transactions'], null, null, 35, 'CASE aplica sinal de negocio antes de somar por pedido.', array['select', 'draft'], 19, false),
  ('00000000-0000-0000-0000-000000000510', '00000000-0000-0000-0000-000000000210', 'Revisao final categorias', 'revisao-final-categorias-inativo', 'free_select', 'hard', 'Com CTEs `category_sales` e `category_stock`, retorne `category_name`, `sales_total` e `total_stock` para categorias com `sales_total > 500`. Ordene por `sales_total` decrescente.', null, 'WITH category_sales AS (SELECT c.name AS category_name, sum(oi.line_total) AS sales_total FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id JOIN challenge_data.order_items oi ON oi.product_id = p.id GROUP BY c.name), category_stock AS (SELECT c.name AS category_name, sum(p.stock_quantity) AS total_stock FROM challenge_data.categories c JOIN challenge_data.products p ON p.category_id = c.id GROUP BY c.name) SELECT s.category_name, s.sales_total, st.total_stock FROM category_sales s JOIN category_stock st ON st.category_name = s.category_name WHERE s.sales_total > 500 ORDER BY s.sales_total DESC', array[]::text[], array['categories', 'products', 'order_items'], null, null, 35, 'Esse desafio revisa CTEs, JOIN entre CTEs, filtro e ordenacao.', array['select', 'draft'], 20, false)
